(window.GIM_TS=window.GIM_TS||{})["Eruvin.8"]={"from":192,"a":[["\u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: כל דבר שהוא משום שבות אינו עומד בפני כתבי הקודש. אימא סיפא\u0004 \u0005[אמור את סוף\u0006 המשנה\u0005]\u0006 \u0003ר' יהודה אומר: אפילו אין מסולק מן הארץ אלא מלא החוט גוללו אצלו. ר' שמעון אומר: אפילו בארץ עצמה גוללו אצלו,\u0004 ואם נאמר שהתנא הראשון אף הוא ר' שמעון, ואם כן נצטרך לומר כי","\u0003רישא\u0004 \u0005[ראשה]\u0006 של המשנה כפי שהסברנו, \u0003וסיפא\u0004 \u0005[וסופה]\u0006 כפי המפורש לפי \u0003ר' שמעון,\u0004 ואילו \u0003מציעתא\u0004 \u0005[אמצעה]\u0006 \u0003ר' יהודה:\u0004 וזה דבר תמוה! \u0003אמר רב יהודה: אין\u0004 \u0005[כן]\u0006 עלינו לקבל הסבר זה אף שאינו מקובל, ולומר כי \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 \u0003ר' שמעון, מציעתא\u0004 \u0005[אמצעה]\u0006 \u0003ר' יהודה.\u0004","\u0003רבה אמר,\u0004 באופן אחר יש לבאר: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003באיסקופה הנדרסת\u0004 במפתן הנדרס על ידי הרבים \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ומשום בזיון כתבי הקדש שרו רבנן\u0004 \u0005[התירו חכמים]\u0006 לעבור על איסור שבות, שכן יש בכך בזיון ממש לכתבי הקודש אם יהלכו שם.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי:\u0004 אמרנו שאם מתגלגל הספר \u0003תוך ארבע אמות — גוללו אצלו, חוץ לארבע\u0004 אמות — \u0003הופכו על הכתב. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003באיסקופה נדרסת עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003מה לי תוך ארבע אמות מה לי חוץ לארבע אמות,\u0004 שהרי איסור מן התורה אין כאן בכל מקרה אלא שבות בלבד, ומדוע אין מתירים אותה מפני בזיון כתבי הקודש?","\u0003אלא אמר אביי: הכא\u0004 \u0005[כאן]\u0006 \u0003באיסקופה כרמלית\u0004 שרחבה ארבעה טפחים ונמוכה מעשרה, וצידה האחד רשות היחיד והאחר רשות הרבים \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ורשות הרבים עוברת לפניה.\u0004","ואז יובן ההבדל, אם נתגלגל הספר \u0003תוך ארבע אמות\u0004 הרי אפילו \u0003דאי נפיל ומייתי ליה\u0004 \u0005[שאם יפול\u0006 הספר מידו ממש \u0005ויביא אותו]\u0006 \u0003לא אתי\u0004 \u0005[יבוא]\u0006 בכך \u0003לידי חיוב חטאת\u0004 שהרי טלטול מרשות הרבים לכרמלית אינו אלא מדברי חכמים, ועל כן \u0003שרו ליה רבנן\u0004 \u0005[התירו לו חכמים]\u0006 לגוללו אליו, שאין כאן חשש לאיסור תורה.","ואולם אם התגלגל \u0003חוץ לארבע אמות, דאי מייתי ליה, אתי\u0004 \u0005[שאם יביא אותו\u0006 בידו ממש, \u0005יבוא]\u0006 \u0003לידי חיוב חטאת,\u0004 שהרי העברת חפץ ארבע אמות ברשות הרבים אסורה מן התורה, \u0003לא שרו ליה רבנן\u0004 \u0005[התירו לו חכמים]\u0006 אף לגוללו, שמא ישכח ויביאנו כולו בידו בלא גלילה, ויעבור על איסור חמור.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003תוך ארבע אמות נמי\u0004 \u0005[גם כן]\u0006 \u0003נגזר דילמא מעייל\u0004 \u0005[נגזור שמא יכניס]\u0006 את הספר \u0003מרשות הרבים לרשות היחיד\u0004 שבתוך הבית. \u0003וכי תימא\u0004 \u0005[תאמר]\u0006 \u0003כיון\u0004 ש\u0003מפסקת כרמלית\u0004 בין רשות היחיד לרשות הרבים \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש זה, לפי שאין הכנסה ישירה מרשות לרשות, \u0003ו\u0004אולם \u0003האמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: המעביר חפץ מתחלת ארבע\u0004 אמות \u0003לסוף ארבע\u0004 אמות, \u0003והעבירו דרך עליו\u0004 (מעל לראשו) אף שהיה החפץ בגובה שלמעלה מעשרה טפחים, ובמקום זה איננו רשות הרבים אלא מקום פטור, ואולם כיון שבסופו של דבר העבירו ארבע אמות \u0003— חייב.\u0004 ואם כן, אף כאן כשמעביר מרשות הרבים לרשות היחיד דרך כרמלית יש בכך איסור מן התורה.","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003באיסקופה ארוכה, אדהכי והכי\u0004 \u0005[בין כה וכה]\u0006 עד שהוא עובר את כל אורך האיסקופה \u0003מידכר\u0004 \u0005[נזכר]\u0006 ולא יכניס את הספר לרשות היחיד.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003לעולם באיסקופה שאינה ארוכה\u0004 אלא \u0003סתם כתבי הקדש עיוני מעיין בהו\u0004 \u0005[בהם]\u0006 \u0003ומנח להו\u0004 \u0005[ומניח אותם]\u0006 ואין לחשוש שמא יעבור מיד מרשות הרבים לרשות היחיד, אלא ודאי יפסיק וישהה מעט על האסקופה. ומקשים: אף לפי הסבר זה \u0003ליחוש דילמא\u0004 \u0005[נחשוש שמא]\u0006 \u0003מעיין בהו\u0004 \u0005[בהם]\u0006 \u0003ברשות הרבים\u0004 ונח מעט \u0003ועייל להו בהדיא\u0004 \u0005[ומכניס אותם במישרין]\u0006 \u0003לרשות היחיד\u0004 בלא להמתין בכרמלית.","ומשיבים: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 כ\u0003בן עזאי היא,\u0004 ש\u0003אמר: מהלך כעומד דמי\u0004 \u0005[נחשב]\u0006 ולכן העובר דרך הכרמלית נחשב כאילו היה עומד שם, ונמצא שאין עוד העברה ישירה מרשות הרבים לרשות היחיד משום ההפסקה בכרמלית. ושואלים: ונחשוש \u0003דילמא זריק להו מזרק\u0004 \u0005[\u0006ו\u0005שמא זורק אותם\u0006 את הספרים פנימה\u0005]\u0006 ואינו נושאם בידו, וכבר \u0003אמר ר' יוחנן: מודה בן עזאי בזורק\u0004 שהמכניס מרשות הרבים לרשות היחיד וזורקו דרך מקום פטור הריהו חייב.","ומשיבים, \u0003אמר רב אחא בר אהבה: זאת אומרת אין מזרקין כתבי הקודש\u0004 שבזיון הוא להם בכך, וממילא אין לחשוש שמא יזרוק את הספרים ולא יוליכם בידו.","שנינו במשנה שאם \u0003היה קורא\u0004 בספר \u0003בראש הגג\u0004 ונשמט ראש הספר מידו, עד שלא הגיע לתוך עשרה טפחים לארץ גוללו אצלו, ומשהגיע לעשרה טפחים הופכו על הכתב. ועל כך שואלים: \u0003ומי שרי\u0004 \u0005[והאם מותר]\u0006 לעשות כן? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כותבי ספרים תפילין ומזוזות\u0004 הצריכים להפסיק ממלאכתם לפי שעה \u0003לא התירו להן להפך יריעה על פניה\u0004 שלא תתלכלך באבק, \u0003אלא פורס עליה את הבגד\u0004 בדרך כבוד!","ומשיבים: \u0003התם\u0004 \u0005[שם\u0006 בסופרים\u0005]\u0006 \u0003אפשר\u0004 לכסות את הספר ביריעה דרך כבוד, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא אפשר, ואי\u0004 \u0005[ואם]\u0006 \u0003לא אפיך איכא\u0004 \u0005[הופך יש]\u0006 \u0003בזיון כתבי הקודש טפי\u0004 \u0005[יותר],\u0006 ומוטב להופכו, אף כי אין הדבר מן המובחר, מאשר להשאירו גלוי בבזיון.","אמרנו שאם הספר בתוך עשרה טפחים לארץ \u0003הופכו על הכתב,\u0004 אבל אסור לו לגוללו. ושואלים: ומדוע אסור הדבר? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא נח\u0004 הספר ברשות הרבים, ואין איסור בגלילתו כלפי מעלה! \u0003אמר רבא:\u0004 מדובר כאן \u0003בכותל משופע,\u0004 שאמנם לא הגיע הספר לקרקע אבל בכל זאת נח בתחומה של רשות הרבים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: במאי אוקימתא למתניתין\u0004 \u0005[במה העמדת\u0006 הסברת \u0005את משנתנו]\u0006 \u0003בכותל משופע, אימא סיפא\u0004 \u0005[אמור את סוף\u0006 המשנה\u0005]\u0006 \u0003ר' יהודה אומר: אפילו אינו מסולק מן הארץ אלא מלא החוט — גוללו אצלו, והא\u0004 \u0005[והרי]\u0006 \u0003נח ליה\u0004 \u0005[לו]\u0006 הספר ברשות הרבים, ואם כן אין כל חילוק אם נוגע בארץ או לא, שהרי כבר נח!","ומשיבים: \u0003חסורי מיחסרא, והכי קתני\u0004 \u0005[חסרה\u0006 המשנה, \u0005וכך יש לשנותה]:\u0006 \u0003במה דברים אמורים — בכותל משופע, אבל\u0004"],["\u0003בכותל שאינו משופע, למעלה משלשה\u0004 טפחים מן הארץ — \u0003גוללו אצלו, למטה משלשה — הופכו על הכתב.\u0004","במשנה שנינו: \u0003ר' יהודה אומר אפילו אינו מסולק מן הארץ\u0004 אלא מלא החוט — גוללו, כי לדעתו \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003הנחה על גבי משהו\u0004 מסוים, וכל שלא נח ממש על הארץ אינו נחשב כמונח, ומותר להחזירו.","ושואלים: \u0003ואלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רבא: תוך שלשה לרבנן\u0004 \u0005[לחכמים]\u0006 שאין מקבלים את ההנחה ש\"קלוטה (בתוך עשרה טפחים לארץ) כמי שהונחה דמי\", אלא לדעתם \u0003צריך הנחה\u0004 ממש, \u0003לימא כתנאי\u0004 \u0005[האם נאמר כ\u0006אחת מדעות \u0005התנאים]\u0006 \u0003אמרה לשמעתיה\u0004 \u0005[לשמועתו]\u0006 ולא לדעת כל החכמים?!","\u0003אלא\u0004 יש לדחות את ההסבר הקודם ולומר: כל המשנה \u0003כולה\u0004 כשיטת \u0003ר' יהודה היא, וחיסורי מיחסרא, והכי קתני\u0004 \u0005[וחסרה\u0006 המשנה, \u0005וכך יש לשנותה]\u0006 \u0003במה דברים אמורים — בכותל משופע, אבל בכותל שאינו משופע — אפילו פחות משלשה טפחים\u0004 לארץ \u0003גוללו אצלו. שר' יהודה אומר: אפילו אינו מסולק מן הארץ אלא מלא החוט גוללו אצלו.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 משום \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שחייבת להיות \u0003הנחה על גבי משהו,\u0004 וכאשר אין החפץ מונח על גבי דבר ממשי, אף שהוא פחות משלושה טפחים לארץ, אינו נחשב כמונח.","\u0003זיז\u0004 (כעין אדן) \u0003שלפני חלון\u0004 גבוה עשרה טפחים ורחב ארבעה — \u0003נותנין עליו\u0004 חפצים שמוציאים מן הבית דרך החלון \u0003ונוטלין ממנו\u0004 חפצים \u0003בשבת.\u0004","\u0003ב גמרא\u0004 מבררים: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003זיז דמפיק להיכא\u0004 \u0005[שיוצא להיכן],\u0006 \u0003אילימא דמפיק\u0004 \u0005[אם תאמר שיוצא]\u0006 הזיז \u0003לרשות הרבים — ליחוש דילמא נפיל, ואתי לאתויי\u0004 \u0005[נחשוש שמא יפול\u0006 החפץ, וישכח \u0005ויבוא להביאו],\u0006 ויעבור משום מכניס מרשות הרבים לרשות היחיד. \u0003אלא\u0004 תאמר \u0003דמפיק\u0004 \u0005[שיוצא]\u0006 הזיז \u0003לרשות היחיד,\u0004 אם כן \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמותר!","\u0003אמר אביי: לעולם\u0004 תפרש \u0003דמפיק\u0004 \u0005[שיוצא]\u0006 \u0003לרשות הרבים, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"נותנין עליו\" דקתני\u0004 \u0005[ששנינו],\u0006 מדובר ב\u0003כלים הנשברים,\u0004 שגם אם יקרה שיפלו הרי ישברו מיד, ואין כאן איפוא חשש שמא יבוא להכניסם.","ומעירים כי \u0003תניא נמי הכי\u0004 \u0005[שנינו גם כן כך\u0006 בברייתא\u0005]:\u0006 \u0003זיז שלפני החלון, היוצא לרשות הרבים — נותנין עליו קערות וכוסות, קיתוניות\u0004 (כלי שתיה קטנים) \u0003וצלוחיות\u0004 שכולם עשויים זכוכית או חרס, כפי שאמר אביי.","\u0003ומשתמש\u0004 בזיז זה \u0003בכל\u0004 ארכו של \u0003הכותל\u0004 אם היה הזיז על כל אורך הכותל \u0003עד עשרה\u0004 טפחים \u0003התחתונים,\u0004 שזיז הנמצא שם אין משתמשים בו. \u0003ואם יש זיז אחד למטה ממנו,\u0004 והוא למעלה מעשרה — \u0003משתמש בו\u0004 לכל אורך הכותל, \u0003ובעליון אין משתמש בו אלא כנגד חלונו.\u0004","ושואלים: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003זיז\u0004 העליון \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק],\u0006 \u0003אי דלית ביה\u0004 \u0005[אם שאין בו]\u0006 \u0003ארבעה\u0004 על ארבעה טפחים — הרי מבחינת רשויות השבת \u0003מקום פטור הוא, ואפילו כנגד חלונו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ישתמש.\u0004 כי דוקא מפני שאין חשש איסור במקום פטור כשלעצמו, הרי כל המניח על זיז צר כזה שכמעט ודאי שהחפץ יפול מעצמו, הרי זה כאילו זרק את החפץ במישרין לארץ. \u0003ואי אית ביה\u0004 \u0005[ואם יש בו]\u0006 \u0003ארבעה\u0004 טפחים — \u0003בכולי\u0004 \u0005[בכל]\u0006 אורך \u0003הכותל לישתמש\u0004 \u0005[ישתמש].\u0006","\u0003אמר אביי: תחתון דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003ארבעה\u0004 טפחים, \u0003ועליון לית ביה\u0004 \u0005[אין בו]\u0006 \u0003ארבעה\u0004 כפי שנאמר תחילה. אבל אדן ה\u0003חלון\u0004 מבפנים \u0003משלימתו לארבעה\u0004 טפחים ולכן \u0003כנגד חלון — משתמש,\u0004 ש\u0003חורי חלון הוא,\u0004 שהזיז נדון כהמשכו של החלון וכחלק ממנו, אבל \u0003דהאי גיסא ודהאי גיסא\u0004 \u0005[לצד זה או לצד זה]\u0006 של החלון — \u0003אסור.\u0004","\u0003עומד אדם ברשות היחיד ומטלטל\u0004 חפצים המונחים \u0003ברשות הרבים,\u0004 בתוך רשות הרבים עצמה, ואין חוששים שמא ישכח ויכניסם לרשות היחיד. וכן עומד \u0003ברשות הרבים ומטלטל ברשות היחיד, ובלבד שלא יוציא\u0004 ויטלטל בה ברשות הרבים עצמה \u0003חוץ מארבע אמות\u0004 שהרי זה הוא איסור לעצמו.","ואולם \u0003לא יעמוד אדם ברשות היחיד וישתין ברשות הרבים, ברשות הרבים וישתין ברשות היחיד, וכן לא ירוק,\u0004 שהוא כמוציא את הנוזלים הללו מרשות לרשות.","\u0003ר' יהודה אומר\u0004 יתר על כן: \u0003אף משנתלש רוקו בפיו\u0004 ונאסף רוק ממש בתוך הפה, \u0003לא יהלך ארבע אמות עד שירוק,\u0004 שאם לא כן נמצא מטלטל את הרוק הצבור בפיו, והרי הוא כנושא משא.","\u0003מתני ליה\u0004 \u0005[היה משנה,\u0006 מלמד\u0005, לו]\u0006 \u0003רב חיננא בר שלמיא לחייא בר רב קמיה\u0004 \u0005[לפני]\u0006 \u0003רב: לא יעמוד אדם ברשות היחיד ומטלטל ברשות הרבים. אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003שבקת רבנן ועבדת\u0004 \u0005[עזבת\u0006 את שיטת \u0005חכמים ועשית]\u0006 \u0003כר' מאיר\u0004 שהוא מחמיר בכגון זה (לקמן עירובין קא,א), ואינך פוסק כסתם משנתנו?!"],["\u0003הוא סבר\u0004 שפסק כך כי חשב \u0003מדסיפא\u0004 \u0005[מתוך שסופה]\u0006 של המשנה כשיטת \u0003ר' מאיר, רישא נמי\u0004 \u0005[תחילתה גם כן]\u0006 כשיטת \u0003ר' מאיר,\u0004 ולאמיתו של דבר \u0003ולא היא: סיפא\u0004 \u0005[סופה]\u0006 כשיטת \u0003ר' מאיר, ורישא רבנן\u0004 \u0005[ותחילתה\u0006 כשיטת \u0005חכמים].\u0006","שנינו במשנה: \u0003\"ובלבד שלא יוציא חוץ\u0004 לארבע אמות \u0003\",\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003הוציא — חייב חטאת. לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003ל\u0004שיטת \u0003רבא,\u0004 ש\u0003אמר רבא: המעביר חפץ מתחלת ארבע\u0004 אמות \u0003לסוף ארבע\u0004 אמות, \u0003ו\u0004אף ש\u0003העבירו דרך עליו,\u0004 כלומר הגביהו למעלה מראשו, ונמצא שעבר החפץ במקום פטור — בכל זאת \u0003חייב\u0004 משום טלטול ארבע אמות ברשות הרבים. ואף כאן, אף שהוא עומד ברשות היחיד המוגבהת ומעביר את החפץ בגובה הרי זה חייב.","ודוחים: \u0003מי קתני\u0004 \u0005[האם שנינו]\u0006 במפורש: \u0003אם הוציא חייב חטאת? דילמא\u0004 \u0005[שמא]\u0006 \u0003אם הוציא — פטור אבל אסור\u0004 מדברי סופרים, ואינו חייב מן התורה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 מסורת זו בלשון אחרת. וכך דייקו מתחילה: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003הוציא — פטור אבל אסור\u0004 מדברי סופרים, ואם כן \u0003לימא תיהוי תיובתיה\u0004 \u0005[האם נאמר שתהא זו קושיה חמורה]\u0006 על \u0003רבא,\u0004 ש\u0003אמר רבא: המעביר מתחלת ארבע\u0004 אמות \u0003לסוף ארבע\u0004 אמות \u0003והעבירו דרך עליו — חייב!\u0004 ודוחים באותו אופן: \u0003מי קתני\u0004 \u0005[האם שנינו]\u0006 \u0003\"הוציא פטור אבל אסור\"? דילמא\u0004 \u0005[שמא]\u0006 נדייק כך: \u0003אם הוציא — חייב חטאת.\u0004","שנינו במשנה ש\u0003לא יעמוד אדם ברשות היחיד\u0004 וישתין או ירוק לרשות הרבים. \u0003אמר רב יוסף: השתין ורק — חייב חטאת.\u0004","ומקשים: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 כדי שיחשב הטלטול כמלאכת הוצאה בשבת \u0003עקירה\u0004 ממקום שהוא ארבעה טפחים על ארבעה טפחים \u0003והנחה\u0004 של החפץ \u0003מעל גבי מקום ארבעה\u0004 על ארבעה טפחים, שהוא שיעור מקום חשוב, \u0003ו\u0004כאן הרי \u0003ליכא\u0004 \u0005[אין],\u0006 שהרי פיו שממנו יצא הרוק אינו רחב ארבעה טפחים!","ומשיבים: \u0003מחשבתו משויא ליה\u0004 \u0005[עושה אותו]\u0006 \u0003מקום,\u0004 כי ודאי מחשיב אדם את פיו מספיק, והריהו נחשב כמו ארבעה טפחים. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שמחשבתו של אדם קובעת חשיבותו של מקום, ולא הכל נמדד לפי שטח בלבד, \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 ש\u0003אמר רבא: זרק\u0004 חפץ \u0003ונח בפי הכלב או בפי הכבשן — חייב חטאת,\u0004 והרי אפשר לשאול: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 \u0003הנחה על גבי מקום ארבעה טפחים על ארבעה טפחים, וליכא\u0004 \u0005[ואין]\u0006 שם!","\u0003אלא\u0004 אומרים אנו: \u0003מחשבתו\u0004 שרוצה לזרוק את החפץ בפי הכלב \u0003משויא ליה\u0004 \u0005[עושה אותו]\u0006 \u0003מקום, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מחשבה משויא לה\u0004 \u0005[עושה אותו]\u0006 \u0003מקום.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 אם \u0003הוא\u0004 עומד \u0003ברשות היחיד ו\u0004אולם \u0003פי אמה ברשות הרבים, מהו\u0004 הדין, כיצד נדון דבר זה? האם \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003עקירה אזלינן\u0004 \u0005[הולכים אנו],\u0006 והשתן נעקר מתוך גופו שהוא בתחום רשות היחיד, \u0003או בתר\u0004 \u0005[אחר]\u0006 \u0003יציאה אזלינן\u0004 \u0005[הולכים אנו]?\u0006 וכיון שהיציאה היא דרך פי האמה שהוא ברשות הרבים אין בכך איסור, שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד\u0006 השאלה במקומה\u0005].\u0006","במשנה שנינו: \u0003וכן לא ירוק\u0004 מרשות לרשות. \u0003ר' יהודה אומר:\u0004 אף לא יהלך אדם ברוק שכבר נעקר בפיו ארבע אמות. ושואלים: האם הכוונה \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא הפיך בה\u0004 \u0005[הפך בו]\u0006 ברוק בפיו, כלומר אם הצטבר הרוק בפיו אבל לא גלגלו בפיו ליורקו?","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 מי ש\u0003היה אוכל דבילה\u0004 (תאנה מיובשת) של תרומה, ודבלה זו לא נפלו עליה מים ושאר נוזלים, וכאמור בתורה אין דבר מאכל מקבל טומאה לפני שהוכשר לכך בנפילת מים עליו, \u0003בידים מסואבות\u0004 (טמאות בדרגת שני לטומאה שפוסלות את התרומה, כסתם ידים), \u0003והכניס ידו לתוך פיו ליטול\u0004 משם \u0003צרור\u0004 שהיה בפיו, \u0003ר' מאיר מטמא\u0004 את הדבילה משום שהוכשרה הדבילה ברוק שבפיו, וכיון שנגעה היד הטמאה בדבילה פסלה אותה. \u0003ו\u0004אילו \u0003ר' יוסי מטהר,\u0004 שהרוק בעודו בפה אינו נחשב כמשקה להכשרת מאכל לטומאה ואינו מכשיר אלא לאחר שיצא מפיו.","ו\u0003ר' יהודה אומר:\u0004 יש לחלק, אם \u0003היפך בה\u0004 ברוק שבפיו, הרי זה כרוק שנתלש ממקומו ונעשה כמשקה, ולכן \u0003טמא.\u0004 אם \u0003לא היפך בה — טהור!\u0004 משמע שלדעת ר' יהודה רוק שלא הפכו בפיו אינו נחשב עדיין כתלוש.","\u0003אמר ר' יוחנן: מוחלפת השיטה.\u0004 כלומר, יש להחליף את השיטות ולומר כי שיטת ר' יהודה במשנה בענין טומאה הוחלפה בדיעה אחרת, ואם כן אין עוד סתירה.","\u0003ריש לקיש אמר: לעולם לא תחליף,\u0004 ואפשר ליישב גם לפי הנוסחה שבידינו, \u0003והכא במאי עסקינן\u0004 \u0005[וכאן\u0006 במשנתנו \u0005במה אנו עוסקים]?\u0006 \u0003בכיחו\u0004 כלומר בליחת השיעול שלו.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' יהודה אומר: כיחו ונתלש\u0004 לא ילך ארבע אמות ברשות הרבים כשהוא בפיו, \u0003מאי לאו\u0004 \u0005[האם לא\u0006 הכוונה\u0005]\u0006 שהוא הדין גם ל\u0003רוק ונתלש!\u0004 ודוחים: \u0003לא,\u0004 דוקא \u0003כיחו ונתלש,\u0004 ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: כיחו שנתלש, וכן רוקו שנתלש לא יהלך\u0004 ברשות הרבים \u0003ארבע אמות עד שירוק\u0004 אף שלא היפך בו! \u0003אלא מחוורתא כדשנינן מעיקרא\u0004 \u0005[מחוור כפי שתירצנו מתחילה]\u0006 שיש להפוך את השיטות.","מכיון שהוזכר ענין הכיח מביאים עוד, \u0003אמר ריש לקיש:\u0004 מי שפולט \u0003כיח בפני רבו\u0004 הריהו כמזלזל בו, והרי הוא \u0003חייב\u0004 על כך \u0003מיתה\u0004 בידי שמים, \u0003שנאמר \"כל משנאי אהבו מות\"\u0004 (משלי ח, לו) — \u0003אל תקרי \"למשנאי\", אלא למשניאי\u0004 על שהוא משניא את עצמו על ידי יריקה זו.","ותוהים: \u0003והא מינס אניס\u0004 \u0005[והרי אנוס הוא]\u0006 שהרי אין אדם משתעל ופולט כיח אלא מחמת אונס, ומדוע יחשב לו הדבר כעבירה? ומשיבים: במקרה שהיה לו \u0003כיח ורק קאמרינן\u0004 \u0005[וירק\u0006 אותו החוצה \u0005אמרנו]\u0006 שהיה עליו לצאת מלפני רבו ולירוק בחוץ.","\u0003לא יעמוד אדם ברשות היחיד ויושיט ראשו וישתה ברשות הרבים,\u0004 או יעמוד \u0003ברשות הרבים וישתה ברשות היחיד, אלא אם כן הכניס ראשו ורובו למקום שהוא שותה\u0004 ממנו. \u0003וכן בגת.\u0004","ותוהים: \u0003רישא רבנן\u0004 \u0005[תחילתה\u0006 של המשנה, המשנה הקודמת כשיטת \u0005חכמים]\u0006 שמותר לטלטל ברשות אחת מתוך רשות אחרת ואין חוששים, \u0003וסיפא\u0004 \u0005[וסופה\u0006 של משנתנו זו\u0005]\u0006 כ\u0003ר' מאיר\u0004 האוסר להיות ברשות אחת ולטלטל באחרת!","\u0003אמר רב יוסף:\u0004 מדובר כאן \u0003בחפיצין שצריכין לו, ודברי הכל.\u0004 כי אפילו חכמים מסכימים שבכגון זה עשוי הוא לשכוח ולטלטלם אליו, ונמצא עובר על דברי תורה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם היתה \u0003כרמלית\u0004 רשות אחת מהן, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003אמר אביי: היא היא\u0004 ודינה כרשות שמן התורה ואין לחלק. \u0003אמר רבא:\u0004 כיצד יכול אתה לומר דבר זה? הלוא \u0003היא גופא\u0004 \u0005[עצמה\u0006 הכרמלית\u0005]\u0006 הכנסה מרשות אחרת אליה אינה אלא \u0003גזירה\u0004 מדברי חכמים, שאין רשות זו עצמה מן התורה \u0003ואנן ניקום\u0004 \u0005[ואנחנו נעמוד]\u0006 \u0003ונגזור גזירה\u0004 על \u0003גזירה?!\u0004","\u0003אמר אביי\u0004 בהסבר שיטתו: \u0003מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את ההלכה הזו, מדיוק לשון המשנה \u0003מדקתני\u0004 \u0005[ממה ששנינו\u0006 במשנתנו\u0005]\u0006"],["\u0003וכן בגת.\u0004 וגת זו אינה רשות היחיד, שהרי כבר הוזכרה רשות היחיד, אלא ודאי הגת היא כרמלית, הרי שאסור לשתות מכרמלית בעודו עומד ברשות הרבים.","\u0003ורבא אמר:\u0004 אין זו הוכחה כי \"וכן בגת\" לא לענין שבת הוא אלא \u0003לענין מעשר. וכן אמר רב ששת: \"וכן בגת\"\u0004 הריהו \u0003לענין מעשר.\u0004","וביאור הדבר: \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 \u0003שותין על הגת,\u0004 כלומר מותר לשתות את היין כשעומדים בתוך הגת, \u0003בין\u0004 שמוזגים אותו \u0003בחמין ובין\u0004 שמוזגים אותו \u0003בצונן. ופטור\u0004 מלהפריש עליו מעשר, אלו \u0003דברי ר' מאיר.\u0004 כי אין חייבים להפריש מעשר אלא על אכילת קבע, אבל המשקה שלוקחים מהגת ושותים בתוך הגת עצמה אינו אלא שתיה באקראי, ופטור. \u0003ר' אליעזר בר צדוק מחייב\u0004 בכל מקרה, כי לדעתו עצם מזיגת היין במים הריהי דרך שתיית קבע.","\u0003וחכמים אומרים: על ה\u0004יין שנמזג ב\u0003חמין — חייב, ועל הצונן — פטור.\u0004 וטעם הדבר, \u0003מפני שמחזיר את המותר.\u0004 כי היין שנמזג במים צוננים, שופכים את מותרו לגת, ונמצאת שתייתו שתיית ארעי גמורה. ואולם יין שנמזג במים חמים, אין מחזירים אותו לגת, שמא יביא להחמצת המשקה שבגת, ושתייתו היא שתיית קבע. ומה שנאמר במשנתנו \"וכן בגת\" הריהו לדעת ר' מאיר, ובא ללמדנו שההיתר לשתות בלא להפריש הוא רק כשראשו ורובו של השותה בגת.","\u0003קולט\u0004 (מקבל) \u0003אדם\u0004 העומד ברשות הרבים את המים הנוזלים \u0003מן המזחילה\u0004 (מעין מרזב) בתוך כלי, בזמן שהיא \u0003למטה מעשרה טפחים.\u0004 כלומר בתחום רשות הרבים. \u0003ומן הצנור מכל מקום שותה\u0004 מים, אפילו בפיו ולא רק על ידי קליטה, משום שהצינור איננו צמוד כל כך לרשות היחיד, וקצהו מגיע לרשות הרבים ממש.","מלשון המשנה נדייק: \u0003קולט — אין\u0004 \u0005[כן]\u0006 כלומר, מותר לו לקלוט מרחוק, \u0003אבל מצרף\u0004 כלומר לשים כלי או פיו בסמוך למזחילה — \u0003לא.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 לחילוק זה? \u0003אמר רב נחמן: הכא\u0004 \u0005[כאן]\u0006 \u0003במזחילה פחות משלשה\u0004 טפחים \u0003סמוך לגג עסקינן\u0004 \u0005[עוסקים אנו],\u0006 וכלל הוא ש\u0003כל פחות משלשה סמוך לגג, כגג דמי\u0004 \u0005[נחשב]\u0006 מדין לבוד. וגג הבית רשות היחיד הוא, נמצא שמוציא מרשות היחיד לרשות הרבים, ואסור.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003עומד אדם ברשות היחיד ומגביה ידו למעלה מעשרה טפחים\u0004 עד שתהא \u0003פחות משלשה סמוך לגג, וקולט\u0004 בכלי מים היורדים מגג חבירו, \u0003ובלבד שלא יצרף\u0004 בפיו.","וכן \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 להבהיר את הענין מצד אחר: \u0003לא יעמוד אדם ברשות היחיד ויגביה ידו למעלה מעשרה טפחים לפחות משלשה\u0004 טפחים \u0003סמוך לגג ויצרף, אבל קולט הוא ושותה.\u0004","שנינו כי \u0003מן הצינור מכל מקום שותה,\u0004 שהצינור ארוך ובולט החוצה מן הבית יותר משלושה טפחים. \u0003תנא\u0004 \u0005[שנויה\u0006 תוספתא\u0005]:\u0006 \u0003אם יש בצינור\u0004 עצמו רוחב \u0003ארבעה על ארבעה\u0004 טפחים — \u0003אסור\u0004 לעומד ברשות הרבים לצרף אליו \u0003מפני שהוא כמוציא מרשות לרשות,\u0004 שהרי הצינור קובע כעין רשות לעצמו.","\u0003בור\u0004 העומד \u0003ברשות הרבים וחולייתו גבוה עשרה טפחים\u0004 הרי החוליה עצמה רשות היחיד, ולכן \u0003חלון\u0004 בית \u0003שעל גביו,\u0004 כלומר העומד סמוך לבור \u0003ממלאין הימנו,\u0004 מן הבור, \u0003בשבת\u0004 שהרי הוא כמוציא מרשות היחיד לרשות היחיד.","וכן אם היתה \u0003אשפה ברשות הרבים גבוה עשרה טפחים,\u0004 כיון שדינה כרשות היחיד הרי \u0003חלון שעל גביו שופכין לתוכה מים בשבת,\u0004 שמותר להוציא מרשות היחיד לרשות היחיד.","שואלים: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]\u0006 כאן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בסמוכה\u0004 שהבור סמוך לכותל הבית עד שאין הפסק ארבעה טפחים באמצע, \u0003למה לי\u0004 שיהא גובה \u0003חוליא\u0004 של הבור \u0003עשרה\u0004 טפחים? הלוא הבור מן הסתם עמוק מעשרה טפחים, והרי הוא רשות היחיד. וכיון שהוא סמוך, הרי אין רשות הרבים ממש באמצע, ומותר לשאוב ולטלטל את המים מרשות היחיד.","\u0003אמר רב הונא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003ב\u0004מקרה שהיה הבור או האשפה \u0003מופלגת מן הכותל ארבעה\u0004 טפחים. ובין הכותל והבור רשות הרבים, ואין להעביר מרשות היחיד לרשות היחיד דרך רשות הרבים. אבל אם חוליית הבור גבוהה עשרה, הרי השואב מעביר את המים שנשאבו דרך מקום הגבוה עשרה מעל רשות הרבים, והוא מקום פטור.","\u0003וטעמא דאיכא\u0004 \u0005[והטעם\u0006 דוקא \u0005שיש]\u0006 \u0003חוליא\u0004 בת \u0003עשרה\u0004 טפחים, \u0003הא ליכא\u0004 \u0005[הרי אם אין]\u0006 \u0003חוליא עשרה\u0004 נמצא \u0003קא\u0004 \u0005[שהוא]\u0006 \u0003מטלטל מרשות היחיד לרשות היחיד דרך רשות הרבים.\u0004","\u0003ור' יוחנן אמר:\u0004 אין צורך בדקדוק זה \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר כאן \u0003בסמוכה,\u0004 אלא \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]\u0006 \u0003דבור וחולייתו מצטרפין לעשרה\u0004 ואין צריכים שתהא החוליה עצמה גבוהה עשרה טפחים.","שנינו: \u0003אשפה\u0004 גבוהה עשרה טפחים שעומדת \u0003ברשות הרבים\u0004 סמוך לחלון בית — \u0003שופכים אליה מרשות היחיד. ושואלים: ו\u0004כי \u0003לא חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא תנטל אשפה\u0004 כולה או מקצתה ותיעשה רשות הרבים, ומתוך הרגל יוסיפו לשפוך לשם בשבת, ונמצא שהם שופכים לרשות הרבים?","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבין בר רב אדא אמר ר' יצחק: מעשה\u0004 היה \u0003במבוי אחד שצידו אחד כלה לים,\u0004 נמצא שהוא סגור על ידי הים, \u0003וצידו אחד כלה לאשפה, ובא מעשה לפני רבי\u0004 לשאלו האם מבוי זה דינו כמבוי סתום, \u0003ולא אמר בו לא איסור ולא היתר.\u0004","ומסבירים: \u0003היתר לא אמר בו דחיישינן\u0004 \u0005[שחוששים אנו]\u0006 \u0003שמא תנטל אשפה\u0004 ונמצא ששוב אין מחיצה למבוי מצד זה, או שמא \u0003יעלה הים שירטון\u0004 ותימצא רצועה של יבשה המרוחקת מן הים ולא יהו מחיצות למבוי.","וכן \u0003איסור לא אמר בו\u0004 באותו מבוי — \u0003דהא קיימין\u0004 \u0005[שהרי עומדות]\u0006 \u0003מחיצות\u0004 לפי שעה, ולפי שעה בודאי הוא מותר. הרי שאנו חוששים שמא תינטל האשפה, ומדוע אין חוששים כמו כן אף במשנתנו?","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שחוששים לה — היא אשפת \u0003יחיד,\u0004 שחוששים שמא יימלך אותו היחיד בדעתו ויפנה את האשפה. \u0003והא\u0004 \u0005[זו]\u0006 משנתנו — באשפה של \u0003רבים,\u0004 ובודאי תשאר קבועה במקומה ולא יזיזוה משם.","\u0003אילן שהיה מיסך\u0004 (סוכך) \u0003על הארץ\u0004 והיו ענפיו הקיצוניים מתכופפים עד שיצרו כעין סככה סביב לגזעו, \u0003אם אין נופו גבוה מן הארץ שלשה טפחים\u0004 בקצותיו — \u0003מטלטלים תחתיו,\u0004 שנעשה כל השטח שתחת האילן כמקום המוקף מחיצות, ודינו כרשות היחיד.","אם היו \u0003שרשיו גבוהים מן הארץ שלשה טפחים — לא ישב עליהן,\u0004 שאין משתמשים באילן, וכל חלק האילן הגבוה משלושה טפחים מן הקרקע דינו כאילן.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 אילן זה בכל זאת \u0003אין מטלטלין בו\u0004 אם היה השטח שתחתיו \u0003יתר מבית סאתים, מאי טעמא\u0004 \u0005[מה טעם]\u0006 האיסור?"],["\u0003משום דהוי\u0004 \u0005[שהריהו]\u0006 \u0003דירה שתשמישה לאויר,\u0004 כלומר שאינה בנויה לצורך מגורים אף כי יש בה מחיצות, \u0003ו\u0004כלל הוא: \u0003כל דירה שתשמישה לאויר או לצל — אין מטלטלין בה\u0004 אם שטחה \u0003יתר מבית סאתים,\u0004 משום שאיננה מקום דירה גמור וחכמים עשאוה כדין קרפף שאינו רשות היחיד לכל ענין.","נאמר שאם היו \u0003שרשיו\u0004 של האילן \u0003גבוהין מן הארץ\u0004 שלושה אין משתמשים בו. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה זו: \u0003שרשי אילן הבאין\u0004 מן האילן \u0003מלמעלה\u0004 מגובה \u0003שלשה\u0004 טפחים וחוזרים ויורדים \u0003לתוך שלשה\u0004 טפחים סמוך לארץ, מה דינם? \u0003רבה אמר: מותר להשתמש בהן, ורב ששת אמר: אסור להשתמש בהן.\u0004","ומסבירים את טעמיהם, \u0003רבה אמר: מותר להשתמש בהן — שכל פחות משלשה\u0004 טפחים בסמיכות \u0003דארעא\u0004 \u0005[של הארץ] —\u0006 \u0003ארעא\u0004 \u0005[ארץ]\u0006 \u0003היא,\u0004 ומותר להשתמש בו. \u0003רב ששת אמר: אסור להשתמש בהן,\u0004 ש\u0003כיון\u0004 ש\u0003מכח איסור קאתי\u0004 \u0005[באו] —\u0006 \u0003אסורין,\u0004 שהרי החלק שממנו הם צומחים אסור, ולכן אף אלה צריכים להיות אסורים.","ומגבילים את המחלוקת: אותם שורשים \u0003דדמו כמשוניתא\u0004 \u0005[שדומים כצוקים]\u0006 שהם עולים ויורדים, ודאי שהשורשים העבים \u0003דסלקין לעילא\u0004 \u0005[העולים למעלה]\u0006 — \u0003אסורין\u0004 לדברי הכל. אבל השורשים הקטנים יותר שטבעם הוא \u0003דנחתין לתתאי\u0004 \u0005[שיורדים למטה] —\u0006 \u0003שרו\u0004 \u0005[מותרים].\u0006 וביחס ליוצאים \u0003לצדדין\u0004 — הרי זו \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003רבה ורב ששת,\u0004 שלרב ששת אסורים, ולרבה מותרים.","\u0003וכן\u0004 נחלקו רבה ורב ששת ב\u0003אניגרא\u0004 אילן היוצא מתוך תעלה ושורשיו גבוהים וחלק מהם נמוך ונסתר בין גדות התעלה, \u0003וכן\u0004 אילן הצומח \u0003בקרן זוית\u0004 בין שני קירות האם חלקו שבין הקירות ונמוך משלושה טפחים נדון כקרקע.","מסופר, \u0003ההוא דיקלא דהוה\u0004 \u0005[דקל אחד שהיה]\u0006 \u0003לאביי, והוה סליק באיפומא\u0004 \u0005[והיה עולה בארובת הגג].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב יוסף\u0004 לשאלו בענין זה \u0003ושרא ליה\u0004 \u0005[והתיר לו]\u0006 להשתמש אף בחלק הדקל שאינו גבוה יותר משלושה טפחים מעל לגג, כי חלקו התחתון נחשב כמצוי בקרקע.","\u0003אמר רב אחא בר תחליפא: דשרא\u0004 \u0005[\u0006מי \u0005שהתיר]\u0006 \u0003לך,\u0004 כשיטת \u0003רבה שרא לך\u0004 \u0005[התיר]\u0006 \u0003לך\u0004 הסבור שאם חלק מהאילן נמוך ואינו נראה למעלה משלושה טפחים אף שחלקו האחר גבוה מן הארץ למעלה משלושה טפחים הרי הוא כסמוך לארץ ומותר להשתמש בו.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ומה חידש רב אחא בר תחליפא? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שבמקרה זה \u0003אפילו ל\u0004דעת \u0003רב ששת\u0004 הרי זה מותר כי \u0003ביתא כמאן דמלי דמי\u0004 \u0005[הבית כמי שהוא מלא נחשב]\u0006 וכאילו היה מלא באדמה וממילא מותר \u0003להשתמש בפחות משלשה\u0004 טפחים \u0003סמוך לגג, קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב אחא שרב ששת אוסר אף כאן.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003שרשיו גבוהין מן הארץ שלשה טפחים — לא ישב עליהם. היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 \u0005היה הדבר],\u0006 \u0003אי דלא הדרי כיפי\u0004 \u0005[אם\u0006 תאמר \u0005שאין\u0006 השורשים \u0005חוזרים ומתכופפים] —\u0006 \u0003פשיטא\u0004 \u0005[פשוט\u0006 הוא\u0005]\u0006 שודאי הגבוה משלושה אילן הוא, \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003אף על גב דהדרי כיפי\u0004 \u0005[אף על פי שחוזרים ומתכופפים],\u0006 משמע שאם חלקם גבוה מן הארץ, הרי הם אסורים לכל אורכם, וקשה לרבה!","ודוחים: \u0003לא, לעולם\u0004 תפרש ש\u0003לא הדרי כיפי\u0004 \u0005[חוזרים ומתכופפים],\u0006 \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 \u0003שצידו\u0004 ה\u0003אחד\u0004 של האילן \u0003שוה לארץ,\u0004 בכל זאת כיון שבשאר צידיו השורשים גבוהים מן הארץ יותר משלושה טפחים, אסור לשבת אף על זה ששווה לארץ.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003שרשי אילן שגבוהין מן הארץ שלשה טפחים או שיש חלל תחתיהן\u0004 על הארץ \u0003שלשה טפחים, אף על פי שצידו אחד\u0004 של השורש \u0003שוה לארץ — הרי זה לא ישב עליהן, לפי\u0004 הכלל \u0003שאין עולין באילן, ואין נתלין באילן\u0004 בידיו, ואף \u0003אין נשענין באילן\u0004 בשבת.","\u0003ו\u0004כן \u0003לא יעלה באילן מבעוד יום וישב שם כל היום כולו\u0004 בשבת משום שעצם השימוש באילן ולא רק הטיפוס עליו אסור. \u0003אחד אילן\u0004 לענין זה \u0003ואחד כל בהמה\u0004 שאין עולים ואין נתלים עליה, \u0003אבל\u0004 אין האיסור משום עצם טורח הטיפוס, שהרי \u0003בור שיח ומערה\u0004 בין מלאים מים בין לא, \u0003וגדר — מטפס ועולה מטפס ויורד, אפילו הן\u0004 עמוקים \u0003מאה אמה.\u0004","ומעירים: \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003אם עלה\u0004 על אילן — \u0003מותר לירד, ותני חדא\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחת]\u0006 \u0003אסור לירד.\u0004 את הסתירה הזו מתרצים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 \u0003כאן\u0004 שהתירו לרדת — כשעלה \u0003מבעוד יום, כאן\u0004 שאסרו לרדת — כשעלה \u0003משחשיכה.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003הא והא\u0004 \u0005[זו וזו]\u0006 \u0003משחשיכה, ולא קשיא\u0004 \u0005[קשה]\u0006 \u0003כאן\u0004 שהתירו לרדת — שעלה \u0003בשוגג, וכאן\u0004 שאסרו לרדת — כשעלה \u0003במזיד.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003הא והא\u0004 \u0005[זו וזו]\u0006 כשעלה \u0003בשוגג, והכא\u0004 \u0005[וכאן]\u0006 בשאלה אם \u0003קנסו שוגג אטו\u0004 \u0005[משום]\u0006 \u0003מזיד קמיפלגי\u0004 \u0005[נחלקו].\u0006 \u0003מר\u0004 \u0005[חכם\u0006 זה\u0005]\u0006 שאסר לרדת \u0003סבר: קנסינן\u0004 \u0005[קונסים אנו],\u0006 ואף שעלה בשוגג אסרו לו לרדת משום קנס, שלא יבואו אחרים לעלות במזיד ולרדת. \u0003ומר\u0004 \u0005[וחכם\u0006 זה\u0005]\u0006 שהתיר \u0003סבר: לא קנסינן\u0004 \u0005[קונסים אנו].\u0006","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 מחלוקת זו הריהי \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 אחרת. יש קרבנות כגון בכור ומעשר שמזים את דמם על המזבח פעם אחת (מתנה אחת), ויש קרבנות כגון עולה שמזים את דמם בארבע מתנות (שתים שהן ארבע), ואם אירע שדם קרבנות \u0003הניתנין במתנה אחת שנתערבו\u0004 בקרבנות אחרים שאף הם \u0003ניתנין במתנה אחת — ינתנו\u0004 הדמים של התערובת \u0003במתנה אחת,\u0004 וכן \u0003מתן ארבע\u0004 שנתערבו \u0003במתן ארבע — ינתנו במתן ארבע.\u0004","אולם מה עושים אם נתערב דם קרבן שהוא ב\u0003מתן ארבע\u0004 עם קרבן שהוא \u0003במתן אחת? ר' אליעזר אומר: ינתנו\u0004 דמי התערובת \u0003במתן ארבע. ור' יהושע אומר: ינתנו במתנה אחת\u0004 ויועיל לו לכפרתו.","\u0003אמר לו ר' אליעזר\u0004 אם נותן רק מתנה אחת \u0003הרי הוא עובר על \"בל תגרע\"\u0004 שהרי לא היזה את דם העולה כראוי! \u0003אמר לו ר' יהושע:\u0004 ולדבריך כשנותן ארבע מתנות \u0003הרי הוא עובר ב\"בל תוסיף\"\u0004 לגבי דם הבכור.","\u0003אמר ר' אליעזר: לא אמרו\u0004 איסור \"בל תוסיף\" \u0003אלא כשהוא בעצמו,\u0004 ולא כשהוא בתערובת. \u0003אמר לו ר' יהושע:\u0004 אף \u0003לא נאמר \"בל תגרע\" אלא כשהוא בעצמו.\u0004","\u0003ועוד אמר ר' יהושע\u0004 טעם לדבריו: \u0003כשנתת\u0004 ארבע מתנות הרי \u0003עברת על \"בל תוסיף\"\u0004 לגבי קרבן אחד, \u0003ועשית מעשה בידך\u0004 בפועל לעבור על דברי תורה. ואילו \u0003כשלא נתת\u0004 גם אם \u0003עברת על \"בל תגרע\" ולא עשית מעשה בידך.\u0004 ואם חייבים לשנות מדברי תורה, מוטב שיהא זה בדרך של \"שב ואל תעשה\".","ורצה רב הונא בן רב יהושע לומר כי \u0003ל\u0004דעת \u0003ר' אליעזר\u0004 ש\u0003אמר התם\u0004 \u0005[שם]\u0006 בקרבנות \u0003קום עשה עדיף\u0004 אף כשיש שני נימוקים סותרים, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003ירד\u0004 מן האילן. שמוטב לו שיעבור פעם בפעולה של ירידה מן האילן ולא ישאר יושב ומשתמש בו כל השבת. \u0003ל\u0004דעת \u0003ר' יהושע\u0004 ש\u0003אמר התם\u0004 \u0005[שם]\u0006 \u0003שב ואל תעשה עדיף — הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003לא ירד\u0004 מן האילן.","ודוחים את ההשוואה: \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לא היא,\u0004 אינו כן, כי \u0003עד כאן לא\u0004 שמענו ש\u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אליעזר התם\u0004 \u0005[שם]\u0006 \u0003קום עשה עדיף — אלא\u0004 במקרה \u0003דקא עביד\u0004 \u0005[שהוא עושה]\u0006 \u0003מצוה\u0004 בנתינת המתנות העודפות. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 שבירידתו \u0003לא עביד\u0004 \u0005[עושה]\u0006 \u0003מצוה\u0004 כלל, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003לא ירד.\u0004","\u0003ואי נמי\u0004 \u0005[ואו גם כן]\u0006 אפשר לדחות את ההשואה מצד אחר; \u0003עד כאן לא\u0004 שמענו ש\u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יהושע התם\u0004 \u0005[שם]\u0006 \u0003שב ואל תעשה עדיף אלא\u0004"],["\u0003שלא קא עביד איסורא\u0004 \u0005[עושה איסור]\u0006 על ידי הימנעות מעשיה, \u0003אבל הכא דקא עביד איסורא\u0004 \u0005[כאן שהוא עושה איסור]\u0006 בכל רגע שהוא שוהה באילן, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ש\u0003ירד\u0004 ממנו.","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003אחד אילן לח ואחד אילן יבש\u0004 אסור לעלות ולהשתמש בהם, \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003במה דברים אמורים\u0004 שאין עולים — \u0003ב\u0004אילן \u0003לח, אבל ביבש — מותר.\u0004","\u0003אמר רב יהודה: לא קשיא\u0004 \u0005[קשה];\u0006 \u0003כאן\u0004 שאסור — \u0003שגזעו מחליף. כאן — כשאין גזעו מחליף,\u0004 שאילן שהוא יבש כעת ויוכל להתחדש משורשיו לאחר זמן מסויים, הוא האילן היבש שנאסר.","ותוהים: אילן ש\u0003גזעו מחליף יבש קרית ליה\u0004 \u0005[אתה קורא לו],\u0006 והרי אילן כזה אינו יבש כלל! \u0003אלא לא קשיא\u0004 \u0005[קשה],\u0006 מדובר באילן יבש שאין גזעו מחליף, ואולם \u0003כאן\u0004 שהתירו — הריהו \u0003בימות החמה, וכאן שאסרו — בימות הגשמים.\u0004 שבימות החמה רואים הכל שאילן זה מת, אבל בימות הגשמים שיש אילנות רבים שעליהם נושרים אין יודעים איזהו אילן חי ואיזהו מת.","ומקשים: \u0003בימות החמה, הא נתרי פירי\u0004 \u0005[הרי נושרים פירות\u0006 האילן\u0005]\u0006 שנשארו מהשנה שעברה כאשר הוא עולה עליו, ויש לאסור אף בו שמא יבוא להורות היתר לעצמו לתלוש אף בלח! ומשיבים: \u0003בדליכא פירי\u0004 \u0005[בשאין פירות],\u0006 ומקשים: \u0003והא קא נתרי קינסי\u0004 \u0005[והרי נושרים ענפים דקים]!\u0006 ומשיבים: \u0003בגדודא\u0004 \u0005[בכעין עמוד]\u0006 באילן שנשרו ענפיו.","ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004מקום \u0003אפסטיא, ואסר\u0004 לטפס אף \u0003בגדודא!\u0004 ומשיבים: באמת אין איסור בכך, אלא \u0003רב בקעה מצא\u0004 כלומר מצא מקום שהיה פרוץ בעבירה, \u0003וגדר בה גדר,\u0004 ולכן אסר להם אף דברים המותרים.","\u0003אמר רמי בר אבא אמר רב אסי: אסור לאדם שיהלך על גבי עשבים בשבת, משום שנאמר \"\u0004גם בלא דעת נפש לא טוב \u0003ואץ ברגלים חוטא\"\u0004 (משלי יט, ב) שפעמים ההליכה עצמה — חטא היא, שהרי יש חשש שיתלוש עשבים תוך כדי הליכה.","ומעירים: \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003מותר לילך על גבי עשבים בשבת, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אסור.\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שאסור — \u0003בלחים,\u0004 שהוא תולשם ממקום חיותם ואסור משום קצירה. \u0003הא\u0004 \u0005[זו]\u0006 שמותר — \u0003ביבשים,\u0004 שכאילו כבר נתלשו ממקום חיותם ובהליכתו אינו אלא מסיתם ממקומם.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003הא והא\u0004 \u0005[זה וזה]\u0006 \u0003בלחים, ולא קשיא\u0004 \u0005[קשה]\u0006 \u0003כאן\u0004 שהותר — \u0003בימות החמה, כאן\u0004 שנאסר — \u0003בימות הגשמים,\u0004 שאין היובש ניכר.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003הא והא\u0004 \u0005[זה וזה]\u0006 \u0003בימות החמה, ולא קשיא\u0004 \u0005[קשה]\u0006 אלא יש לחלק: \u0003הא\u0004 \u0005[זה]\u0006 שמותר — \u0003דסיים מסאניה\u0004 \u0005[שנעל נעליו]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאסור — ש\u0003לא סיים מסאניה\u0004 \u0005[נעל נעליו]\u0006 והעשבים נכנסים בין אצבעות רגליו ונתלשים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא דסיים מסאניה\u0004 \u0005[זה וזה\u0006 מדובר \u0005כשנעל נעליו]\u0006 \u0003ולא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאסור — \u0003דאית ליה עוקצי\u0004 \u0005[כשיש לו\u0006 לנעל \u0005עוקץ],\u0006 קצה שיכולים העשבים להיאחז בו, ו\u0003הא\u0004 \u0005[זה]\u0006 — \u0003דלית ליה עוקצי\u0004 \u0005[שאין לו עוקץ].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא דאית ליה עוקצי\u0004 \u0005[זה וזה שיש לו עוקץ]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאסור — \u0003דאית ליה שרכא\u0004 \u0005[ש\u0006העשב, \u0005יש לו\u0006 ענפים \u0005נשרכים\u0006 על הארץ\u0005],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמותר — \u0003דלית ליה שרכא\u0004 \u0005[שאין לו\u0006 ענפים \u0005נשרכים\u0006 על הארץ].","ומסכמים: \u0003והאידנא דקיימא לן\u0004 \u0005[ועכשיו שמוחזק לנו\u0006 להלכה\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 שפסק כי דבר שאין מתכוון לעשותו ונעשה מעצמו מותר, הרי אף כאן מאחר שכוונתו רק ללכת שם ולא לתלוש עשבים בשבת, \u0003כולהו שרי\u0004 \u0005[כולם מותרים]\u0006 בכל האופנים הללו.","כיון שהוזכר פסק הלכה הנובע מפסוק זה מוסיפים מה ש\u0003אמר רמי בר חמא אמר רב אסי: אסור לאדם שיכוף אשתו לדבר מצוה\u0004 (תשמיש), \u0003שנאמר \"ואץ ברגלים חוטא\".\u0004 ומתפרש בלשון נקייה.","\u0003ואמר ר' יהושע בן לוי: כל הכופה אשתו לדבר מצוה, הוויין\u0004 \u0005[יהיו]\u0006 \u0003לו בנים שאינן מהוגנין\u0004 כתוצאה מכך. \u0003אמר רב איקא בר חיננא: מאי קראה\u0004 \u0005[מהו המקרא]\u0006 המרמז על כך — \u0003\"גם בלא דעת נפש לא טוב\"\u0004 (משלי יט, ב) כלומר, אם הבעילה היתה שלא מדעת האשה, גם נפש הילד לא תהא טובה.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 \u0003\"גם בלא דעת נפש לא טוב\" — זה הכופה אשתו לדבר מצוה. \"ואץ ברגלים חוטא\" — זה הבועל ושונה,\u0004 ומצער בכך את אשתו.","על דבר זה תוהים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 והרי \u0003אמר רבא: הרוצה לעשות כל בניו זכרים יבעול וישנה!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 \u0003כאן\u0004 שנתן רבא עצה זו — הרי זה כשהדבר הוא \u0003לדעת\u0004 האשה ובהסכמתה, \u0003כאן\u0004 שאין לעשות כן — \u0003שלא לדעת.\u0004","\u0003ג\u0004 וכיון שדובר בעניני היחסים שבין איש ואשתו מביאים מה ש\u0003אמר ר' שמואל בר נחמני אמר ר' יוחנן: כל אשה שתובעת בעלה לדבר מצוה — הווין\u0004 \u0005[יהיו]\u0006 \u0003לה בנים שאפילו בדורו של משה לא היו כמותן.\u0004 ש\u0003אילו בדורו של משה כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"הבו לכם אנשים חכמים ונבנים וידעים לשבטיכם\u0004 ואשימם בראשיכם\u0003\"\u0004 (דברים א, יג), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 אחר כך: \u0003\"ואקח את ראשי שבטיכם אנשים חכמים וידעים\u0004 ואתן אותם ראשים עליכם\u0003\"\u0004 (דברים א, טו). \u0003ואילו נבונים לא אשכח\u0004 \u0005[מצא],\u0006 שאף שמצא חכמים וידועים, אבל לא נבונים שהם יותר מאשר חכמים.","\u0003ואילו\u0004 ל\u0003גבי לאה כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ותצא לאה לקראתו ותאמר אלי תבוא כי שכר שכרתיך\u0004 בדודאי בני\u0003\"\u0004 (בראשית ל, טז), ומה היה שכרה? שנולד לה יששכר, ועליו \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ומבני יששכר יודעי בינה לעתים לדעת מה יעשה ישראל ראשיהם מאתים וכל אחיהם על פיהם\"\u0004 (דברי הימים א יב, לג).","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]\u0006 וכי נאה לאשה שתתבע את בעלה?! \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יצחק בר אבדימי: עשר קללות נתקללה חוה\u0004 בשל חטא עץ הדעת, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"אל האשה אמר הרבה ארבה עצבונך והרונך בעצב תלדי בנים ואל אשך תשוקתך והוא ימשול בך\" (בראשית ג, טז), ומפרש:","\u0003\"אל האשה אמר הרבה ארבה\" — אלו שני טפי דמים\u0004 מיוחדים לאשה והיא מצטערת בהם \u0003אחת דם נדה ואחת דם בתולים, \"עצבונך\" — זה צער גידול בנים, \"והרנך\" — זה צער העיבור, \"בעצב תלדי בנים\" — כמשמעו\u0004 שהוא צער הלידה,","\u0003\"ואל אישך תשוקתך\" — מלמד שהאשה משתוקקת על בעלה\u0004 למשל \u0003בשעה שיוצא לדרך, \"והוא ימשל בך\" — מלמד שהאשה תובעת בלב,\u0004 ואינה מפרשת רצונה מתוך בושה, \u0003והאיש תובע בפה.\u0004 ומעירים \u0003זוהי מדה טובה בנשים\u0004 שהן תובעות בלב ולא בפה. הרי שאין ראוי לאשה שתתבע את בעלה!","ומשיבים: \u0003כי אמרינן\u0004 \u0005[כאשר אמרנו]\u0006 בזכות האשה התובעת את בעלה אין הכוונה שתאמר לו בפירוש בפה, אלא \u0003דמרציא ארצויי קמיה\u0004 \u0005[שתתרצה לפניו]\u0006 ויבין מדעתו מה כוונתה. \u0003ד\u0004כיון שהובא המאמר בדבר עשר קללות של חוה דנים בו: וכי עשר הן?","הלוא \u0003הני\u0004 \u0005[הרי]\u0006 \u0003שבע\u0004 בלבד \u0003הויין\u0004 \u0005[הן]!\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר\u0004 מה הן הנוספות; \u0003עטופה כאבל\u0004 שחייבת האשה בכיסוי ראשה, \u0003ומנודה מכל אדם, וחבושה בבית האסורין\u0004 שדרכה תמיד להיות בבית.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מנודה מכל אדם? אילימא\u0004 \u0005[אם תאמר ]\u0006 \u0003משום דאסיר\u0004 \u0005[שאסור]\u0006 \u0003לה ייחוד\u0004 עם גברים, \u0003איהו נמי אסיר ליה\u0004 \u0005[הוא גם כן\u0006 הגבר \u0005אסור לו ]\u0006 \u0003ייחוד\u0004 עם נשים, ואין זה מיוחד לאשה. \u0003אלא דאסירא לבי תרי\u0004 \u0005[שאסורה\u0006 להנשא \u0005לשנים]\u0006 מה שאין כן הגבר שמותר בשתי נשים.","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנינו]\u0006 \u0003מגדלת שער כלילית\u0004 (שד), \u0003ויושבת ומשתנת מים כבהמה, ונעשית כר\u0004 (מצע) \u0003לבעלה\u0004 בשעת תשמיש, אלה שלוש הקללות הנוספות.","\u0003ואידך\u0004 \u0005[ו\u0006החכם \u0005האחר]\u0006 שאינו מונה אלה בין הקללות מה סבור הוא? ומשיבים כי לדעתו \u0003הני שבח הוא\u0004 \u0005[\u0006דברים \u0005אלה שבחים הם]\u0006 \u0003לה\u0004 ולא צער, אם משום צניעות ואם משום נוחות.","ולגבי ענין משתנת מים \u0003אמר ר' חייא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"מלפנו מבהמות ארץ ומעוף השמים יחכמנו\"\u0004 (איוב לה, יא) ומפרשים: \u0003\"מלפנו מבהמות\"\u0004 — כלומר לומדים אנו דברים טובים מבהמות \u0003זו פרידה שכורעת ומשתנת מים,\u0004 ולמדנו מכאן דרך צניעות. \u0003\"ומעוף השמים יחכמנו\"\u0004 — \u0003זה תרנגול שמפייס\u0004 את התרנגולת \u0003ואחר כך בועל.\u0004","וכעין זה \u0003אמר ר' יוחנן: אילמלא\u0004 \u0005[גם אם]\u0006 \u0003לא ניתנה תורה,\u0004 בכל זאת \u0003היינו למידין צניעות מחתול\u0004 שמכסה את צואתו, \u0003וגזל מנמלה\u0004 שאינה לוקחת חיטה מנמלה אחרת, \u0003ועריות מיונה\u0004 שבני הזוג נאמנים זה לזה. ומעירים: \u0003דרך ארץ מתרנגול שמפייס ואחר כך בועל,\u0004","\u0003ומאי\u0004 \u0005[ובמה]\u0006 \u0003מפייס\u0004 אותה את התרנגולת? \u0003אמר רב יהודה אמר רב\u0004 מתנועותיו לפני הבעילה נראה כאילו \u0003הכי קאמר\u0004 \u0005[כך אומר\u0006 הוא\u0005]\u0006 \u0003לה\u0004 לתרנגולת: \u0003זביננא ליך זיגא דמטו ליך עד כרעיך\u0004 \u0005[אקנה לך מעיל שיגיע לך עד הרגלים],\u0006 \u0003לבתר הכי\u0004 \u0005[לאחר\u0006 הבעילה \u0005כך]\u0006 \u0003אמר לה: לישמטתיה לכרבלתיה דההוא תרנגולא אי אית ליה ולא זביננא ליך\u0004 \u0005[תשמט כרבלתו של תרנגול זה אם יש לי כסף ולא אקנה לך]\u0006 אלא שאין בידו כסף לשם כך."],["\u0003הדלת שבמוקצה\u0004 דלת הפונה אל החצר שמאחורי הבית, וכרגיל אינה דלת גמורה כתקונה אלא רק לוח עץ שאינו קבוע בצירים, וסותמים בו את הפתח. וכן \u0003חדקים\u0004 (מחיצות עשויות קוצים) שמעמידים \u0003בפרצה, ומחצלות — אין נועלין בהן\u0004 את הדלתות שהנועל אותם הרי הוא כבונה או משלים בנין \u0003אלא אם כן\u0004 היו \u0003גבוהים מן הארץ.\u0004","\u0003ורמינהו\u0004 \u0005[מקשים,\u0006 מראים סתירה ממקור אחר\u0005]\u0006 שנינו: \u0003דלת הנגררת\u0004 על הארץ או \u0003מחצלת הנגררת, וקנקן הנגרר\u0004 המשמשים לנעילת הפתח, \u0003בזמן\u0004 שהם \u0003קשורין ותלויין\u0004 במקום — \u0003נועלין בהן בשבת, ואין צריך לומר ביום טוב\u0004 משמע שהכל תלוי בהיותם תלוים ואפילו אינם גבוהים מן הארץ!","\u0003אמר אביי:\u0004 מדובר כאן \u0003בשיש להם ציר\u0004 וכיון שכך הריהם כדלת גמורה, \u0003רבא אמר: בשהיה להן ציר\u0004 קודם לכן וניכר שיש עליהן צורת דלת.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 שנינו: \u0003דלת הנגררת ומחצלת הנגררת וקנקן הנגרר, בזמן שקשורין ותלויין וגבוהים מן הארץ אפילו\u0004 כ\u0003מלא נימא — נועלין בהן, ואם לאו — אין נועלין בהן!\u0004 הרי שבכל זאת דרוש שיהיו אף גבוהים מן הארץ.","\u0003אביי מתרץ לטעמיה\u0004 \u0005[לשיטתו]\u0006 \u0003ורבא מתרץ לטעמיה\u0004 \u0005[לשיטתו];\u0006 \u0003אביי מתרץ לטעמיה\u0004 \u0005[לשיטתו]\u0006 כך: שיש להוסיף \u0003או שיש להן ציר, או שגבוהין מן הארץ. רבא מתרץ לטעמיה\u0004 \u0005[לשיטתו]:\u0006 \u0003כשהיה להן ציר או שגבוהין מן הארץ.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003סוכי קוצים\u0004 (ערימות קוצים) \u0003וחבילין שהתקינן\u0004 לסתימת \u0003פירצה שבחצר, בזמן שקשורין ותלויין — נועלין בהן בשבת, ואין צריך לומר ביום טוב.\u0004","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: דלת אלמנה הנגררת — אין נועלין בה.\u0004 ושאלו: \u0003היכי דמי\u0004 \u0005[כיצד היא\u0006 בדיוק\u0005]\u0006 \u0003דלת אלמנה? איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שזהו כינוי של דלת שעשויה \u0003חד שיפא\u0004 \u0005[קרש אחד]\u0006 שאינה נראית כדלת, \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 \u0003דלית ליה גשמה\u0004 \u0005[שאין לה מפתן]\u0006 (גאונים) והיא נוגעת בארץ בשעת סגירה.","כיון שדובר בפעולות האסורות משום שהן דומות לבניה מביאים מה ש\u0003אמר רב יהודה: האי מדורתא\u0004 \u0005[מדורה זו]\u0006 אם מסדרים את העצים \u0003ממעלה למטה\u0004 שמחזיקים לפי שעה את העצים העליונים באויר ואחר כך שמים את התחתונים — \u0003שרי\u0004 \u0005[מותר]\u0006 ביום טוב, \u0003ממטה למעלה — אסיר\u0004 \u0005[אסור]\u0006 משום שסידור העצים כדרכו הוא כדרך בנין.","\u0003וכן ביעתא\u0004 \u0005[ביצים]\u0006 כשמסדרים בערימה, \u0003וכן קידרא\u0004 \u0005[קדירה]\u0006 ששופתים על כירה, \u0003וכן פוריא\u0004 \u0005[מיטה]\u0006 שמרכיבים, \u0003וכן חביתא\u0004 \u0005[חבית]\u0006 אם מסדר חביות במרתף, שיש להחזיק העליונות באויר ולסדר את התחתונות בתחילה.","כיון שהוזכרו חדקים שבפירצה מביאים דבר בהקשר זה; \u0003אמר ליה ההוא מינא\u0004 \u0005[לו מין אחד]\u0006 \u0003לר' יהושע בן חנניא: חדקאה\u0004 \u0005[איש-קוץ]!\u0006 \u0003דכתיב בכו\u0004 \u0005[שנאמר בכם]\u0006 \u0003\"טובם כחדק\"\u0004 (מיכה ז, ד) הרי שאפילו טובי ישראל אינם אלא כקוצים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שטיא, שפיל לסיפיה דקרא\u0004 \u0005[שוטה, רד לסוף מקרא זה]\u0006 שכן נאמר \u0003\"ישר ממסוכה\"\u0004 ואין זה ביטוי גנאי אלא לכוונת שבח הוא. \u0003ואלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"טובם כחדק\" — כשם שחדקים הללו מגינין על הפירצה, כך טובים שבנו מגינים עלינו. דבר אחר: \"טובם כחדק\"\u0004 (חדק = הדק) \u0003שמהדקין את אומות העולם לגיהנם, שנאמר \"קומי ודושי בת ציון כי קרנך אשים ברזל ופרסתיך אשים נחושה והדקות עמים רבים\u0004 והחרמתי לה' בצעם וחילם לאדון כל הארץ\u0003\"\u0004 (מיכה ד, יג).","\u0003לא יעמוד אדם ברשות היחיד ויפתח\u0004 במפתח המצוי \u0003ברשות הרבים,\u0004 וכן לא יעמוד \u0003ברשות הרבים ויפתח ברשות היחיד\u0004 שמא ישכח ויכניס אליו את המפתח ונמצא מוציא מרשות לרשות, \u0003אלא אם כן עשה מחיצה גבוה עשרה טפחים\u0004 סביב לדלת ויעמוד בתוכה, אלה \u0003דברי ר' מאיר.\u0004","\u0003אמרו לו: מעשה בשוק של פטמים\u0004 (מפטמי עופות לאכילה. ר\"ח) \u0003שהיה בירושלים, שהיו נועלין\u0004 את דלתותיהם ועומדים ברשות הרבים \u0003ומניחין את המפתח בחלון שעל גבי הפתח\u0004 שהוא גבוה מעשרה טפחים, ולא חששו לאיסור בדבר. \u0003ר' יוסי אומר:\u0004 אותו מקום \u0003שוק של צמרים הוה\u0004 \u0005[היה].\u0006","ושואלים: \u0003ורבנן\u0004 \u0005[ו\u0006אותם \u0005חכמים]\u0006 שהביאו את המעשה בפטמי ירושלים, \u0003אמר\u0004 להם \u0003ר' מאיר\u0004 הלכה שלא יעמוד אדם ברשות היחיד ויפתח ב\u0003רשות הרבים — ומהדרו אינהו\u0004 \u0005[והם משיבים\u0006 לו\u0005]\u0006 בענין \u0003כרמלית\u0004 שהרי \u0003אמר רבה בר בר חנה אמר ר' יוחנן: ירושלים אלמלא דלתותיה ננעלות בלילה — חייבין עליה משום רשות הרבים.\u0004 וכיון שלמעשה דלתותיה ננעלות הריהי כולה ככרמלית, וכיצד מביאים הוכחה משוקי ירושלים!","\u0003אמר רב פפא: כאן\u0004 שאין ירושלים כרשות הרבים — \u0003קודם שנפרצו בה פרצות\u0004 בחומתה ומשום דלתותיה אינה בתורת רשות הרבים שהרי הן ננעלות, \u0003כאן\u0004 במשנה — \u0003לאחר שנפרצו בה פרצות,\u0004 ודינה איפוא כרשות הרבים.","\u0003רבא אמר: סיפא אתאן\u0004 \u0005[בסוף\u0006 המשנה \u0005הגענו]\u0006 לענין אחר, כלומר הקטע האחרון במשנה אינו תשובה לדברי ר' מאיר שבמשנה אלא מתייחס לבעיה דומה, לענין \u0003שערי גינה\u0004 שיש בשטחה יותר מכבית סאתים שהם כרמלית, \u0003והכי קאמר\u0004 \u0005[וכך אמר]\u0006 כלומר, כך יש להבין ולהוסיף בדברי המשנה: \u0003וכן לא יעמוד ברשות היחיד\u0004 כגון חצירו \u0003ויפתח בכרמלית\u0004 כגון גינה, \u0003בכרמלית ויפתח ברשות היחיד,\u0004"],["\u0003אלא אם כן עשה מחיצה גבוהה עשרה טפחים\u0004 ועומד בתוכה, אלו \u0003דברי ר' מאיר. אמרו לו\u0004 חכמים: \u0003מעשה בשוק של פטמים שהיה בירושלים, שהיו נועלין\u0004 את דלתותיהם \u0003ומניחין את המפתח בחלון שעל גבי הפתח\u0004 שהיה גבוה מעשרה טפחים. \u0003ר' יוסי אומר:\u0004 לא של פטמים אלא \u0003שוק של צמרים היה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003פתחי שערי גינה\u0004 הסמוכים לרשות הרבים ומקום המנעול רחב ארבעה טפחים וגבוה עשרה שדינו כרשות היחיד, \u0003בזמן שיש להן בית שער מבפנים — פותח ונועל מבפנים,\u0004 יש להם בית שער \u0003מבחוץ — פותח ונועל מבחוץ,\u0004 שהרי אינו אלא כמעביר מרשות היחיד לרשות היחיד, היה להם בית שער \u0003מכאן ומכאן\u0004 גם פנימה וגם החוצה — \u0003פותח ונועל כאן וכאן, אין להן לא לכאן ולא לכאן — אסורין כאן וכאן,\u0004 שהרי אין מקום שיוכל לטלטל בו את המפתח.","\u0003וכן חנויות הפתוחות לרשות הרבים, בזמן שהמנעול\u0004 מצוי \u0003למטה מעשרה\u0004 טפחים הוא איפוא בתחום רשות הרבים — \u0003מביא מפתח מערב שבת ומניחו באיסקופה\u0004 שדינה ככרמלית, ו\u0003למחר\u0004 עומד על האיסקופה \u0003פותח ונועל ומחזירו לאיסקופה,\u0004","\u0003ובזמן שהמנעול למעלה מעשרה — מביא מפתח מערב שבת ומניחו במנעול, למחר פותח ונועל ומחזירו למקומו,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: אף בזמן שהמנעול למעלה מעשרה טפחים מביא מפתח מערב שבת, ומניחו באיסקופה, למחר פותח ונועל ומחזירו למקומו, או\u0004 מניחו \u0003בחלון שעל גבי הפתח.\u0004","אבל \u0003אם יש בחלון ארבעה על ארבעה\u0004 נמצא שחלון זה הוא רשות היחיד שהרי יש בו שטח של ארבעה על ארבעה טפחים בגובה עשרה \u0003ואסור מפני שהוא כמוציא מרשות\u0004 כרמלית \u0003לרשות\u0004 היחיד.","ומדייקים: \u0003מדקאמר\u0004 \u0005[ממה שאמר]\u0006 \u0003\"וכן חנויות\" מכלל,\u0004 מכאן ש\u0003באיסקופת כרמלית עסקינן\u0004 \u0005[עוסקים אנו]\u0006 כאן. ואם כן נברר \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003מנעול\u0004 שדברנו בו \u0003היכי דמי\u0004 \u0005[כיצד היה בדיוק]?\u0006 \u0003אי דלית ביה\u0004 \u0005[אם אין בו]\u0006 \u0003ארבעה\u0004 על ארבעה טפחים, אם כן אין בו דין רשות כלל ו\u0003מקום פטור הוא.\u0004","\u0003ואי אית ביה\u0004 \u0005[ואם יש בו]\u0006 \u0003ארבעה\u0004 על ארבעה טפחים \u0003בהא\u0004 \u0005[בזה]\u0006 \u0003לימא רבנן\u0004 \u0005[יאמרו חכמים]:\u0006 \u0003אף בזמן שהמנעול למעלה מעשרה מביא מפתח מערב שבת ומניחו באיסקופא, למחר פותח ונועל בו ומחזירו לאיסקופה\u0004 שעל גבי הפתח \u0003או לחלון שעל גבי הפתח?\u0004 שהרי אם המנעול הוא בגובה עשרה טפחים וברוחב ארבעה דינו כרשות היחיד. \u0003והא\u0004 \u0005[והרי]\u0006 הוא \u0003מטלטל מכרמלית לרשות היחיד!\u0004","\u0003אמר אביי: לעולם\u0004 יש לפרש ש\u0003אין בו\u0004 במנעול \u0003ארבעה\u0004 על ארבעה טפחים, \u0003ו\u0004אולם \u0003יש בו\u0004 מקום מספיק בדלת שמסביב לו כדי \u0003לחוק\u0004 \u0005[לחקוק]\u0006 לעשות בו חור \u0003ולהשלימו לארבעה\u0004 טפחים.","\u0003ובהא פליגי\u0004 \u0005[וב\u0006דבר \u0005זה נחלקו]\u0006 \u0003ר' מאיר\u0004 הולך לשיטתו ש\u0003סבר חוקקין להשלים\u0004 שבמקום שיש בו נקב קטן אם המקום רחב מספיק עד שאפשר להשלים את הנקב ולעשות בו חלל גדול יותר, דנים אנו כאילו היה כבר חקוק ועומד. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כשיטתם ש\u0003אין חוקקין להשלים\u0004 והמנעול כפי שהוא אין בו שיעור מקום חשוב ואינו אלא מקום פטור.","\u0003אמר רב ביבי בר אביי: שמע מינה מהא מתניתא תלת\u0004 \u0005[למד ממנה\u0006 מברייתא זו \u0005שלושה\u0006 דברים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי \u0003חוקקין להשלים\u0004 לדעת ר' מאיר. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 ש\u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003ר' מאיר\u0004 מדבריו ביחס ל\u0003שערי גינה,\u0004 שהרי התיר לעמוד ברשות שמדברי סופרים ולפתוח ברשות אחרת,","\u0003ושמעת מינה\u0004 \u0005[ולומד אתה מזאת]\u0006 כי \u0003מדרבנן איתא\u0004 \u0005[מ\u0006דברי \u0005חכמים יש]\u0006 לקבל את דברי \u0003רב דימי, דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל מסר בשם \u0003ר' יוחנן: מקום שאין בו ארבעה על ארבעה — מותר לבני רשות הרבים ולבני רשות היחיד לכתף עליו\u0004 משאם \u0003ובלבד שלא יחליפו\u0004 מרשות לרשות. ומקור לדברים בהלכה זו שלא יחליפו הוא בדעת חכמים האומרים שאם מונח המפתח במקום ארבעה על ארבעה טפחים, אסור לעמוד באיסקופה שהיא כרמלית וליטול משם את המפתח אף שאין צריך להעבירו אלא למנעול שהוא מקום פטור, מכל מקום חששו שמא יעבירנו בטעות לרשותו ונמצא מוציא מרשות לרשות.","נגר (בריח ניצב ששמים בדלת כדי לקובעה בקרקע) \u0003שיש בראשו גלוסטרא\u0004 (קצה עבה) שאפשר להשתמש בו לכמה צרכים, נחלקו בו אם דינו ככלי ומותר לסגור בו, או שהוא נחשב כקורה והמשתמש בו הריהו כבונה. \u0003ר' אליעזר אוסר ור' יוסי מתיר.\u0004","\u0003אמר ר' אליעזר: מעשה בכנסת\u0004 (בבית הכנסת) \u0003שבטבריא שהיו נוהגין בו\u0004 בנגר שיש בו גלוסטרא \u0003היתר, עד שבא רבן גמליאל והזקנים ואסרו להן. ר' יוסי אומר:\u0004 מעשה שהיה להיפך היה: \u0003איסור נהגו בו,\u0004 בנגר זה, \u0003ובא רבן גמליאל והזקנים והתירו להן.\u0004","בגמרא מצמצמים את המחלוקת; \u0003בניטל באגדו\u0004 כלומר אם היה נגר זה יכול להטלטל על ידי האגד (חבל או דבר אחר הקושר אותו לדלת) — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שדינו כחלק מן הדלת ומותר לנעול בו, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 ר' יוסי ור' אליעזר"],["\u0003בשאינו ניטל באגדו,\u0004 שהחוט דק מכדי שיטלטל בו את הנגר, \u0003דמר\u0004 \u0005[שחכם זה,\u0006 ר' יוסי\u0005]\u0006 \u0003סבר: כיון\u0004 ש\u0003יש בראשו גלוסטרא — תורת כלי עליו\u0004 ומותר לנעול בו. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר\u0005]\u0006 \u0003סבר: כיון\u0004 ש\u0003אינו ניטל באיגדו,\u0004 שהחוט שאיננו חזק כדי להחזיק בו את הנגר — \u0003לא\u0004 נקרא כלי גמור רק משום הגלוסטרא ואסור להשתמש בו.","\u0003נגר הנגרר\u0004 בריח הקשור בדלת אבל מתוך שהחוט ארוך איננו תלוי בה אלא נגרר על הארץ — \u0003נועלין בו\u0004 בשבת \u0003במקדש,\u0004 שאין האיסור בדבר זה אלא משום שבות, ולא גזרו שבות במקדש, \u0003אבל לא במדינה\u0004 כלומר מחוץ למקדש.","\u0003והמונח\u0004 שאינו קשור כלל \u0003כאן וכאן — אסור\u0004 שהוא כבונה. \u0003ר' יהודה אומר: המונח — מותר במקדש, והנגרר במדינה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו נגר הנגרר שנועלין\u0004 בשבת \u0003במקדש אבל לא במדינה — כל שקשור ותלוי, וראשו אחד מגיע לארץ,\u0004 זהו נגר הנגרר. \u0003ר' יהודה אומר:\u0004 נגר כ\u0003זה — אף במדינה מותר, אלא איזהו נגר שנועלין במקדש אבל לא במדינה — כל שאינו קשור\u0004 בדלת \u0003ולא תלוי, ושומטו\u0004 לאחר שימוש בו \u0003ומניחו בקרן זוית.\u0004","\u0003אמר רב יהודה אמר שמואל: הלכה כר' יהודה בנגרר\u0004 שמותר אף במדינה אבל לא במונח, שאף במקדש אסור,","\u0003אמר רבא: והוא שקשור בדלת\u0004 עצמה. ותוהים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' טבלא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003למחוזא, וחזא לההוא דהוה תלי בעיברא דדשא\u0004 \u0005[וראה\u0006 נגר \u0005אחד שהיה תלוי בבריח הדלת]\u0006 \u0003ולא אמר להו\u0004 \u0005[להם]\u0006 \u0003ולא מידי\u0004 \u0005[דבר\u0006 לאסור\u0005]?\u0006 ודוחים: \u0003ההוא\u0004 \u0005[אותו\u0006 נגר\u0005]\u0006 \u0003ניטל באיגדו הוה\u0004 \u0005[היה],\u0006 והקשור בחבל כזה מודים שמותר לטלטלו אפילו אינו קשור בדלת עצמה.","מסופר: \u0003רב אויא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לנהרדעא, חזייה לההוא גברא דהוה קא קטיר בגמי\u0004 \u0005[ראה אדם אחד שהיה קושר ב\u0006חוט של \u0005עשב]\u0006 את הנגר. \u0003אמר: דין לא נטרוק\u0004 \u0005[דלת זו לא יסגור]\u0006 בשבת, שקשר כזה איננו נחשב.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא: נקמז\u0004 כלומר נגר היורד בתוך הנקב שבאסקופה עד לאדמה, \u0003מהו? אמר רב יוסף: מאי תיבעי ליה\u0004 \u0005[מה מסופק בעיניו]\u0006 וכי \u0003לא שמיע ליה הא דתניא\u0004 \u0005[ידוע לו זו ששנינו\u0006 בתוספתא\u0005]:\u0006 \u0003נשמט\u0004 מהחבל בו היה קשור — \u0003אסור, נקמז — מותר. ור' יהודה אמר: נקמז, אף על פי שאינו נשמט\u0004 לגמרי — \u0003אסור.\u0004","\u0003ואמר רב יהודה אמר שמואל: הלכה כר' יהודה בנקמז.\u0004 ושואלים: \u0003וטעמא מאי\u0004 \u0005[ומה הטעם]\u0006 שאסרו בנקמז? \u0003אמר אביי: משום דמיחזי\u0004 \u0005[שנראה]\u0006 \u0003כבונה\u0004 שהרי הוא נכנס בתוך האדמה.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב נחומי בר זכריה מאביי: עשה לו\u0004 לאותו נגר \u0003בית יד\u0004 להחזיקו ואינו קשור, \u0003מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בוכנא קאמרת\u0004 \u0005[מקבת אומר אתה\u0006 לי\u0005]\u0006 שכיון שעשה לו בית יד הריהו ככלי גמור ובכלי הכל מודים שמותר להשתמש. וכן \u0003איתמר\u0004 \u0005[נאמר]\u0006 הדבר בדרך אחרת, ש\u0003אמר רב נחומי בר אדא: עשה לו בית יד מותר.\u0004","מסופר: \u0003ההוא שריתא דהוה בי\u0004 \u0005[קורה אחת שהיתה בבית]\u0006 \u0003רבי פדת, דהוה מדלו ליה בי\u0004 \u0005[והיו מרימים אותה]\u0006 \u0003עשרה\u0004 אנשים מרוב כובדה \u0003ושדו לה אדשא\u0004 \u0005[והיו מניחים אותה על הדלת]\u0006 כדי לנעלה, \u0003ולא אמר להו\u0004 \u0005[להם]\u0006 \u0003ולא מידי\u0004 \u0005[דבר\u0006 לאסור\u0005]\u0006 \u0003אמר:\u0004 מדוע מתיר אני — כי \u0003תורת כלי עליה,\u0004 שכיון שהיא נראית ככלי ועשויה לצורך מסוים מותר להשתמש בה בשבת.","מסופר עוד: \u0003ההיא אסיתא דהות בי\u0004 \u0005[אותה מכתשת שהיתה בביתו]\u0006 של \u0003מר שמואל, דהוה מחזקת אדריבא\u0004 \u0005[שהיתה מחזיקה חצי כור]\u0006 \u0003שרא\u0004 \u0005[התיר]\u0006 \u0003מר שמואל למישדייה אדשא\u0004 \u0005[להניח אותה ליד הדלת]\u0006 כדי לסוגרה. אמר: \u0003תורת כלי עליה,\u0004 ומותר לסגור בה והעושה כן אינו כבונה.","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רמי בר יחזקאל לרב עמרם: נימא לן מר מהלין מילי מעלייתא דאמרת לן משמיה\u0004 \u0005[יאמר לנו אדוני מאותם דברים מעולים שאמרת לנו משמו]\u0006 של \u0003רב אסי\u0004 בדבר \u0003כיפי דארבא\u0004 \u0005[\u0006המוטות \u0005הכפופים שבספינה],\u0006 \u0003שלח ליה\u0004 \u0005[לו],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב אסי: הני כיפי דארבא\u0004 \u0005[אותם\u0006 המוטות \u0005הכפופים שבספינה]\u0006 \u0003בזמן שיש בהן טפח, אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003אין בהן טפח ואין בין זה לזה שלשה\u0004 טפחים שדינו כלבוד — \u0003למחר\u0004 בשבת, \u0003מביא מחצלת ופורס עליהן.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 התירו — \u0003מוסיף על אהל עראי הוא, ושפיר דמי\u0004 \u0005[ומותר]\u0006 שהרי המוטות הללו עצמם מהוים כעין אהל, ואם מניח מחצלת עליהם אינו אלא מוסיף על האהל.","מסופר: \u0003הנהו דכרי דהוו ליה\u0004 \u0005[אילים שהיו לו]\u0006 \u0003לרב הונא, דביממא בעו טולא ובליליא בעו אוירא\u0004 \u0005[שביום היו צריכים להיות בצל\u0006 מפני החום \u0005ובלילה היו צריכים אויר]\u0006 וחפשו דרך שבלילה אף בשבת לא יהא כיסוי בדיר וביום יוכל להיות. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב\u0004 לשאול,","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל כרוך בודייא\u0004 \u0005[לך כרוך מחצלות]\u0006 שהיו שם פרושות לצל, ואל תכרכם לגמרי אלא \u0003שייר\u0004 (השאר) \u0003בה טפח\u0004 אחד מכוסה, \u0003למחר פשטה\u0004 \u0005[פשוט]\u0006 את המחצלת כולה ויהא זה \u0003מוסיף על אהל עראי הוא, ושפיר דמי\u0004 \u0005[ומותר].\u0006","\u0003אמר רב משום\u0004 \u0005[בשם]\u0006 \u0003ר' חייא: וילון מותר לנטותו ומותר לפורקו ולנטותו בשבת\u0004 שאינו אהל, אלא קיר בלבד, ואם אינו קבוע בחזקה במקום אחד אין בו איסור.","\u0003כילת חתנים\u0004 (יריעה הפרושה מעל המיטה) \u0003מותר לפורקה ולנטותה בשבת. אמר רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: לא אמרן\u0004 \u0005[אמרנו\u0006 הלכה זו\u0005]\u0006 \u0003אלא\u0004 אם פרושה מעל המיטה ומשופעת לשני צידיה ו\u0003אין בגגה\u0004 של כילה זו \u0003טפח, אבל יש בגגה טפח\u0004 שאין השיפוע חד, אלא היריעה פרושה למעלה טפח בצורה ישרה וממנו מתחילה להשתפע, שמכיון שטפח זה נחשב כאהל לכן \u0003אסור.\u0004","וכן \u0003וכי אין בגגה טפח לא אמרן\u0004 \u0005[אמרנו]\u0006 היתר זה \u0003אלא שאין\u0004 בתוך השיפוע הפנימי \u0003בפחות משלשה\u0004 טפחים \u0003סמוך לגג\u0004 רוחב \u0003טפח, אבל יש בפחות משלשה\u0004 טפחים \u0003סמוך לגג\u0004 רוחב \u0003טפח — אסור.\u0004","וכן כאשר \u0003אין בפחות משלשה\u0004 טפחים \u0003סמוך לגג טפח נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא שאין\u0004"],["\u0003בשיפועה\u0004 כלומר שאינה מתרחבת עם תחתית השיפוע הסמוך למיטה עד כדי שיהיה \u0003טפח\u0004 ממרכזו לכל צד, \u0003אבל יש בשיפועה טפח\u0004 — הרי \u0003שיפועי אהלים כאהלים דמו\u0004 \u0005[נחשבים]\u0006 והרי כילה זו כאוהל — ואסורה.","\u0003ואמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: סיינא\u0004 (כובע לבד נוקשה) — \u0003שרי\u0004 \u0005[מותר]\u0006 לחובשו בשבת, ואין בכך משום אהל. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שכובע כזה \u0003אסור!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאסור — \u0003דאית ביה\u0004 \u0005[שיש בו]\u0006 בשוליו רוחב \u0003טפח, הא\u0004 \u0005[זה]\u0006 שמותר — \u0003דלית ביה\u0004 \u0005[שאין בו]\u0006 בשוליו רוחב \u0003טפח.\u0004","ותוהים: \u0003אלא מעתה שרביב בגלימיה\u0004 \u0005[אם ימשוך בטליתו]\u0006 ויוציאנה מעבר לראשו \u0003טפח, הכי נמי\u0004 \u0005[גם כן יהא]\u0006 \u0003אסור?\u0004 והרי מלבוש הוא זה!","\u0003אלא\u0004 יש לדחות את דרך ההסבר הקודמת ולומר שאין טעם האיסור משום עשיית אהל אלא משום חשש לטלטול ברשות הרבים אם יפול הכובע. ו\u0003לא קשיא\u0004 \u0005[קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמותר \u0005—\u0006 \u0003דמיהדק\u0004 \u0005[כשמהודק]\u0006 הכובע בראשו, ומכיון שאין לחשוש שמא יפול הכובע ויבוא לטלטלו, מותר לחובשו, \u0003הא\u0004 \u0005[זה] —\u0006 ש\u0003לא מיהדק\u0004 \u0005[מהודק],\u0006 ויש לחשוש שיפול מראשו ויבוא לטלטלו ברשות הרבים.","\u0003מחזירין\u0004 בשבת \u0003ציר התחתון\u0004 של דלת שידה תיבה ומגדל שנשמטה \u0003במקדש,\u0004 שאין בכך אלא משום שבות, ובמקדש לא גזרו על השבות, \u0003אבל לא במדינה\u0004 שהדבר אסור משום שבות. ציר \u0003העליון — כאן וכאן אסור,\u0004 כי בכך יש משום בניה ומלאכה מן התורה, שאסורה בכל מקום. \u0003ר' יהודה אומר:\u0004 ציר \u0003העליון במקדש\u0004 — מותר, \u0003והתחתון\u0004 מותר אף \u0003במדינה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ציר\u0004 התחתון של \u0003דלת שידה\u0004 (מזווה) \u0003תיבה ומגדל\u0004 (ארון), \u0003במקדש — מחזירין\u0004 למקומו, ו\u0003במדינה\u0004 — רק \u0003דוחקין\u0004 אותו להחזירו. וציר \u0003העליון — כאן וכאן לא יחזיר, גזירה שמא יתקע\u0004 בחוזק ויעשה מלאכה ממש, \u0003ואם תקע — חייב חטאת\u0004 שהוא כבונה.","ו\u0003של בור ושל דות ושל יציע — לא יחזיר\u0004 כלל, \u0003ואם החזיר — חייב חטאת,\u0004 שרק בדלתות כלים המיטלטלים היה מקום לחלק, שספק אם יש בהן איסור בניה, אולם כל דבר המחובר לקרקע ודאי אסור לתקנו משום מלאכת \"בונה\".","\u0003מחזירין רטיה\u0004 (תחבושת) שהוסרה מן הפצע \u0003במקדש\u0004 בשבת, שאין גוזרים שמא יבוא להחליק את המשחה, ויעבור משום מלאכת \"ממחק\", \u0003אבל לא במדינה.\u0004 ו\u0003אם בתחילה\u0004 להניח תחבושת כזו על פצע לא חבוש ביום השבת עצמו — \u0003כאן וכאן אסור.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003רטיה שפרשה\u0004 (ירדה) \u0003מעל גבי מכה — מחזירין\u0004 אותה \u0003בשבת\u0004 בכל מקום. \u0003ר' יהודה אומר:\u0004 אם \u0003הוחלקה למטה — דוחקה למעלה, למעלה — דוחקה למטה,\u0004 אף מותר שיהא \u0003מגלה מקצת הרטיה ומקנח פי המכה\u0004 מצד אחד, \u0003וחוזר ומגלה מקצת רטיה\u0004 מצד אחר \u0003ומקנח פי המכה\u0004 מאותו צד, אולם","\u0003רטיה עצמה לא יקנח, מפני שהוא ממרח\u0004 וזו תולדה של מלאכת \"ממחק\" האסורה מן התורה. \u0003ואם מירח — חייב חטאת,\u0004 ואילו להחזיר ממש — אסור בכל מקרה.","\u0003אמר רב יהודה אמר שמואל: הלכה כר' יהודה. אמר רב חסדא: לא שנו\u0004 חכמים שמותר להחזיר \u0003אלא שפירשה\u0004 הרטיה ונפלה \u0003על גבי כלי\u0004 שעשויה מיד להרימה ולהחזירה, \u0003אבל\u0004 אם \u0003פירשה על גבי קרקע — דברי הכל אסור,\u0004 שהוא כחובש פצעו בתחילה.","\u0003אמר מר בר רב אשי: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 \u0003אבא, נפלה ליה אבי סדיא, וקא מהדר ליה\u0004 \u0005[לו\u0006 הרטיה \u0005על הכר, והחזיר אותה],\u0006 \u0003אמינא ליה\u0004 \u0005[אמרתי לו]:\u0006 \u0003לא סבר לה מר להא\u0004 \u0005[האם אין אדוני סבור\u0006 כאמרה \u0005זו]\u0006 ש\u0003אמר רב חסדא: מחלוקת — שפירשה על גבי כלי, אבל פירשה על גבי קרקע — אסור, ואמר שמואל: הלכה כר' יהודה\u0004 שפסק ההלכה הוא שאין להחזיר רטיה שנפלה אף על גבי כלי!","\u0003אמר לי: לא שמיע לי\u0004 \u0005[שמעתי\u0006 דבר זה\u0005]\u0006 \u0003כלומר\u0004 התכוון לומר \u0003לא סבירא לי\u0004 \u0005[איני סבור]\u0006 כהלכה זו של רב חסדא שנחלקו רק כאשר נפלה רטיה על הכלים, אלא אף כשנפלה על הקרקע מחלוקת, והלכה שמותר.","\u0003קושרין\u0004 בשבת \u0003נימא\u0004 (מיתר) שניתקה מכינור שמנגנים בו \u0003במקדש, אבל לא במדינה. ואם בתחילה\u0004 להצמיד את הנימה בכינור ולקשרו שם \u0003כאן וכאן אסור.\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא אחרת: \u0003נימת כנור שנפסקה — לא היה קושרה אלא עונבה,\u0004 משמע שקשירה אסורה אפילו במקדש! ומתרצים \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא האוסרת — \u0003רבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים]\u0006 \u0003והא\u0004 \u0005[זו] —\u0006 כשיטת \u0003ר' אליעזר.\u0004","ומבארים: \u0003ל\u0004שיטת \u0003ר' אליעזר\u0004 ש\u0003אמר \"מכשירי מצוה דוחין את השבת\"\u0004 וכיון שקשירת הנימה היא לצורך מצוה, לכן אף \u0003קושרה.\u0004 ואילו \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 שמכשירי מצוה \u0003אין דוחין\u0004 את השבת, רק \u0003עונבה.\u0004","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 האמור במשנה הוא כשיטת \u0003ר' אליעזר\u0004 המתיר לעשות מכשירי מצוה אף על ידי חילול שבת, אם כן \u0003אפילו\u0004 לא נפסקה אלא אף \u0003לכתחילה נמי\u0004 \u0005[גם כן]\u0006 יהא מותר לשים את הנימה שהרי לצורך מצוה היא!","\u0003אלא\u0004 לא כך יש להבין, ויש ליישב: \u0003לא קשיא\u0004 \u0005[קשה].\u0006 \u0003הא\u0004 \u0005[זו]\u0006 המשנה המתירה — היא כשיטת \u0003ר' יהודה\u0004 הסבור שעניבה דינה כקשירה לכל דבר, ולכן אין הבדל. \u0003והא\u0004 \u0005[זו]\u0006 האוסרת — כ\u0003רבנן\u0004 \u0005[חכמים]\u0006 האומרים שעניבה אין בה איסור מן התורה, ולכן התירו לענוב נימה.","על כך שואלים: \u0003ור' יהודה אליבא דמאן\u0004 \u0005[על פי\u0006 שיטתו \u0005של מי]\u0006 לפי איזו שיטה אמר דבריו?"],["\u0003אי אליבא\u0004 \u0005[אם על פי]\u0006 שיטת \u0003ר' אליעזר\u0004 אמר, מדוע מותר רק בדיעבד \u0003אפילו לכתחילה נמי\u0004 \u0005[גם כן]\u0006 יהא מותר, שהרי לדעת ר' אליעזר עושים מכשירי מצוה בשבת.","\u0003אלא\u0004 יש לדחות את הביאור הקודם ולהסביר בדרך אחרת: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 האוסרת — כשיטת \u0003ר' שמעון, והא\u0004 \u0005[וזו]\u0006 המתירה — כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בן לוי שנפסקה לו נימא בכנור — קושרה, ר' שמעון אומר: עונבה.\u0004 שנראה מכאן שמודים חכמים אלה להתיר מכשירי מצוה שאי אפשר לעשותם מבעוד יום, ור' שמעון מחמיר.","\u0003ר' שמעון בן אלעזר אומר: אף היא\u0004 נימה הקשורה \u0003אינה משמעת את הקול\u0004 כראוי, ויש כאן עבירה בלא לעשות את המצוה כתיקונה, \u0003אלא משלשל\u0004 את המיתר \u0003מלמטה וכורך\u0004 על היתד המיועד למתיחת המיתרים עד שישמיעו צליל ראוי \u0003מלמעלה או משלשל מלמעלה וכורך מלמטה.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003הא והא רבנן\u0004 \u0005[זו וזו\u0006 כשיטת \u0005חכמים]\u0006 והתירו לעשות מכשירי מצוה שאין לעשותם מבעוד יום. \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]\u0006 \u0003כאן\u0004 שהתירו לקשור מדובר כשהיה הקרע \u0003באמצע\u0004 שאם יענבו שם יפגם הצליל, ו\u0003כאן\u0004 שאמרו לענוב מדובר שנקרע \u0003מן הצד\u0004 בקצה הנימה שאפשר לו על ידי עניבה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003הא והא\u0004 \u0005[זו וזו]\u0006 כשנקרע \u0003באמצע,\u0004 והמחלוקת היא בין ר' שמעון וחכמים \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' שמעון\u0005]\u0006 \u0003סבר: גזרינן\u0004 \u0005[גוזרים אנו]\u0006 לאסור אף על קשירה באמצע מחשש שמא יבואו לקשור אף מן הצד כשאין צורך בכך, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר: לא גזרינן\u0004 \u0005[גוזרים אנו].\u0006","\u0003חותכין\u0004 ביד \u0003יבלת\u0004 בשבת \u0003במקדש,\u0004 שהיבלת היא מום כל עוד מצויה היא בבהמת הקרבן או בכהן העובד, ואם חתכוה — הותרה הבהמה להקרבה וכהן לעבודה, ונמצא שיש בחיתוך זה צורך העבודה, \u0003אבל לא במדינה. ואם\u0004 בא לחתוך \u0003בכלי — כאן וכאן אסור.\u0004","\u0003ורמינהו\u0004 \u0005[ומקשים\u0006 על כך ממקור אחר\u0005]\u0006 שנאמר בו: \u0003הרכיבו\u0004 (הרכבתו) של קרבן פסח על הכתפיים \u0003והבאתו מחוץ לתחום וחתיכת יבלתו\u0004 כדי להכשירו לקרבן אינם \u0003דוחין\u0004 את השבת כאשר חל ערב פסח בשבת, \u0003ר' אליעזר אומר\u0004 כשיטתו: \u0003דוחין,\u0004 וקשה מדברי המשנה שלנו על דברי חכמים שם!","בתירוץ קושי זה נחלקו \u0003ר' אלעזר ור' יוסי בן חנינא; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: הא והא\u0004 \u0005[זה וזה]\u0006 מדובר ביבלת \u0003לחה, ולא קשיא\u0004 \u0005[קשה]\u0006 \u0003כאן\u0004 שמותר — מדובר שמסירה \u0003ביד\u0004 שאינה דרך מלאכה, ו\u0003כאן\u0004 שאסור — מדובר שמסירה \u0003בכלי.\u0004","\u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: הא והא\u0004 \u0005[זו וזו]\u0006 שמורידים את היבלת \u0003ביד ולא קשיא\u0004 \u0005[קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאסרו — ביבלת \u0003לחה,\u0004 וזה שהתירו — \u0003ביבישה\u0004 שאין בהסרתה משום מלאכה.","ומקשים: \u0003ולמאן דאמר\u0004 \u0005[ולדעת זה שאומר]\u0006 \u0003\"הא\u0004 \u0005[זו]\u0006 \u0003ביד הא\u0004 \u0005[זו]\u0006 \u0003בכלי\" מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר \"הא\u0004 \u0005[זו]\u0006 \u0003בלחה הא\u0004 \u0005[זו]\u0006 \u0003ביבישה\"\u0004 והוצרך להסבר אחר? \u0003אמר לך: יבישה אפילו בכלי נמי שרי\u0004 \u0005[גם כן מותר]\u0006 להסירה, \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003איפרוכי איפרכא\u0004 \u0005[שהיא\u0006 מתפוררת \u0005ונפרכת]\u0006 מעצמה, והחותכה לא חתך אלא דבר מת.","\u0003ולמאן דאמר\u0004 \u0005[ולדעת זה שאומר]\u0006 \u0003\"הא\u0004 \u0005[זו]\u0006 \u0003בלחה והא\u0004 \u0005[וזו]\u0006 \u0003ביבישה\", מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר \"הא\u0004 \u0005[זו]\u0006 \u0003ביד הא\u0004 \u0005[זו]\u0006 \u0003בכלי\"?\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003בכלי — הא תנן\u0004 \u0005[הרי שנינו]\u0006 במפורש במשנתנו \u0003אם בכלי — כאן וכאן\u0004 (במקדש ובמדינה) \u0003אסור\u0004 ולא היה צורך לחזור ולשנות בדיני פסחים שאסור להוריד יבלת בכלי.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 כיצד הוא מתרץ זאת — \u0003הא דקתני התם\u0004 \u0005[זה ששנינו שם]\u0006 שנית הלכה זו \u0003משום דקא בעי איפלוגי\u0004 \u0005[שרצה\u0006 להביא \u0005את המחלוקת]\u0006 בין \u0003ר' אליעזר ורבנן\u0004 \u0005[וחכמים]\u0006 להשמיענו שר' אליעזר חולק וסבור שאפילו בכלי מותר.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 כיצד עונה הוא לנימוק זה? ואומרים שלדעתו חתיכת היבלת \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003הרכיבו והבאתו מחוץ לתחום קתני\u0004 \u0005[שנינו]\u0006 שאין בהם איסור תורה ולא נאסרו אלא מ\u0003דרבנן.\u0004 ואף בענין חתיכת היבלת מדובר בודאי רק באיסור שמדברי סופרים, ולא בחתיכה בכלי.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 סבור כי אף בשאר הפרטים אין האיסורים מדברי סופרים אלא מדברי תורה ממש. כיצד: \u0003הרכיבו דלא\u0004 כשיטת \u0003ר' נתן,\u0004 ש\u0003אמר\u0004 ר' נתן: \u0003החי נושא את עצמו\u0004 ולכן אין בהרכבתו משום טלטול ואינו אסור אלא מדברי סופרים, ואם אין מקבלים הלכה זו הרי המרכיב את הפסח עובר משום נושא ומעביר ברשות הרבים. ו\u0003הבאתו מחוץ לתחום כ\u0004שיטת \u0003ר' עקיבא,\u0004 ש\u0003אמר: תחומין דאורייתא\u0004 \u0005[מן התורה].\u0006","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף\u0004 על הסבר זה מתוך משנה שבה נאמר, \u0003אמר ר' אליעזר: קל וחומר, ומה שחיטה\u0004 של הפסח \u0003שהיא\u0004 אסורה כרגיל \u0003משום מלאכה — דוחה\u0004 במקדש \u0003את השבת,\u0004 דברים \u0003אלו\u0004 כגון הרכבתו, הבאתו וחתיכת יבלתו שהן \u0003משום שבות אינו דין שידחו את השבת?\u0004 אלא יש לדחות את התירוץ הקודם וודאי שאף שם מדובר רק באיסורים מדברי חכמים.","\u0003אמר רב יוסף: הא והא\u0004 \u0005[זו וזו]\u0006 \u0003ביד,\u0004 מדובר בהורדת היבלת ביד, שיש בה רק משום שבות, ואת הסתירה יש ליישב כך: לעבור על \u0003שבות מקדש\u0004 בתוך תחום בית ה\u0003מקדש\u0004 עצמו — \u0003התירו, שבות דמקדש במדינה — לא התירו\u0004 ולכן, אף שמלאכות אלה בקרבן הפסח הן רק שבות והדבר נוגע לעבודת המקדש, כיון שהוא נעשה מחוץ למקדש לא התירו חכמים.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003אביי\u0004 עם תלמידי חכמים \u0003וקאמר להא שמעתא\u0004 \u0005[ואמר את ההלכה הזו]\u0006 של רב יוסף \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב ספרא לאביי:\u0004 שנינו, \u0003היה קורא בספר\u0004 מספרי הקודש העשוי כמגילה ויושב \u0003על האיסקופה ונתגלגל הספר מידו\u0004 לרשות הרבים \u0003גוללו אצלו. והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003שבות דמקדש במדינה הוא\u0004 הדבר, ובכל זאת \u0003לא גזרינן דילמא נפיל ואתי לאיתויי\u0004 \u0005[גוזרים אנו שמא יפול\u0006 הספר \u0005ויבוא להביאו]\u0006 ויטלטל ברשות הרבים. משמע שאף מחוץ לתחום המקדש לא גזרו משום שבות בדברים המקודשים!","ודחה אביי: \u0003ו\u0004כי \u0003לא אוקימנא\u0004 \u0005[העמדנו]\u0006 משנה זו שמדובר \u0003באסקופה כרמלית ורשות הרבים עוברת לפניה,\u0004 ש\u0003כיון\u0004 ש\u0003איגדו בידו\u0004 (שמחזיק ואוגד את צידו האחר של הספר בידו) — \u0003אפילו שבות נמי ליכא\u0004 \u0005[גם כן אין]\u0006 שעצם גלילת הספר והבאתו אצלו מרשות הרבים לכרמלית מותרת מדברי תורה, ובספר קודש לא גזרו חכמים לאסור בו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רב ספרא ממקור אחר: נאמר ש\u0003משלשלין את הפסח לתנור\u0004 לאחר שזרקו את דמו והוציאו לחוץ לצלותו בערב שבת \u0003עם חשיכה, והא הכא\u0004 \u0005[והרי כאן]\u0006 בצלייה בשבת שאינה אלא שבות ובקרבן פסח שהוא \u0003שבות\u0004 של ה\u0003מקדש במדינה\u0004 ובכל זאת \u0003לא גזרינן\u0004 \u0005[גוזרים אנו]\u0006 בקרבן פסח כמו בשאר צלי \u0003שמא יחתה בגחלים.\u0004 הרי שלצורך דבר מקודש אין שבות אפילו מחוץ לתחום המקדש!","\u0003אישתיק\u0004 \u0005[שתק]\u0006 ולא מצא תשובה. \u0003כי אתא לקמיה\u0004 \u0005[כאשר בא\u0006 אביי \u0005לפני]\u0006 \u0003רב יוסף, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר לי רב ספרא\u0004 והקשה על דבריך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא תשני ליה\u0004 \u0005[תתרץ לו]:\u0006 \u0003בני חבורה\u0004 המנויה על הקרבן העוסקים בצליית קרבן הפסח ודאי \u0003זריזין\u0004 הן ומדקדקים במצוות וסומכים אנו עליהם שלא יבואו לעבור, מה שאין כן בסתם אנשים.","ומעירים: \u0003ואביי\u0004 משום מה לא תירץ כך? מפני שלדעתו הנימוק \u0003\"כהנים זריזין\" — אמרינן\u0004 \u0005[אומרים אנו]\u0006 ומשתמשים בו, שכיון שהן רגילים כל ימיהם בעבודת המקדש בזריזות אינם טועים ובאים לידי עבירה, אבל \u0003בני חבורה זריזין הן — לא אמרינן\u0004 \u0005[אומרים אנו]\u0006 שכיון שאינם מורגלים בזהירות יתרה יתכן שישכחו.","\u0003רבא אמר\u0004 שיש לתרץ את הסתירה בין המשניות בדרך אחרת, ומשנתנו המתירה לחתוך יבלת לשיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר מכשירי מצוה דוחין את השבת\u0004 ולכן מותר לחותכה ביד. ואם תאמר, אם כן מדוע אין לעשות זאת בכלי? \u0003מודה ר' אליעזר,\u0004 ש\u0003כמה\u0004 ש\u0003אפשר לשנויי\u0004 \u0005[לשנות]\u0006 שלא יהיה בכך איסור מן התורה, \u0003משנינן\u0004 \u0005[משנים אנו]\u0006 להדגיש את קדושת השבת."],["\u0003מאי היא\u0004 \u0005[מה הוא]\u0006 המקור לסברה זו, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כהן שעלתה בו יבלת\u0004 ונפסל לפיכך לעבודה — \u0003חבירו חותכה לו בשיניו.\u0004 ונדייק: \u0003בשיניו — אין\u0004 \u0005[כן],\u0006 \u0003בכלי — לא. חבירו — אין\u0004 \u0005[כן],\u0006 \u0003איהו\u0004 \u0005[הוא\u0006 עצמו\u0005]\u0006 — \u0003לא.\u0004","ומעתה נחקור: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו? \u0003אילימא רבנן\u0004 \u0005[אם תאמר\u0006 שכשיטת \u0005חכמים\u0006 היא\u0005]\u0006 \u0003ובמקדש, כיון דאמרי רבנן בעלמא\u0004 \u0005[שאומרים חכמים בכלל]\u0006 שדבר זה אסור \u0003משום שבות\u0004 — \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003מה לי הוא מה לי חבירו,\u0004 מה ההבדל בין אם עשה זאת הוא ובין אם עשה זאת חבירו?","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 כשיטת \u0003ר' אליעזר\u0004 ש\u0003אמר: בעלמא\u0004 \u0005[בכלל]\u0006 \u0003חייב חטאת\u0004 על הסרת יבלת וצפרנים, \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003אף\u0004 שלשיטתו \u0003מכשירי מצוה דוחין את השבת,\u0004 ולכאורה צריך היה להתיר אפילו לו עצמו לחתוך את היבלת אף בכלי, בכל זאת \u0003כמה\u0004 ש\u0003אפשר לשנויי משנינן\u0004 \u0005[לשנות משנים].\u0006","את ההוכחה הזו דוחים: \u0003לא,\u0004 אין מוכרח, \u0003לעולם\u0004 תאמר שברייתא זו כשיטת חכמים היא, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003עלתה\u0004 היבלת \u0003בכריסו\u0004 או במקום כיוצא בו שקל להסירה ביד — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ברור לחכמים שאין כל הבדל בינו לבין חבירו ויכול אף הוא בעצמו להסירה.","\u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שעלתה לו נשיכה\u0004 ואגב כך יבלת \u0003בגבו\u0004 או \u0003באצילי ידיו, דאיהו לא מצי שקיל לה\u0004 \u0005[שהוא איננו יכול להוריד אותה]\u0006 אלא רק אחר.","ושואלים: \u0003ואי רבנן נשקליה ניהליה\u0004 \u0005[ואם\u0006 כשיטת \u0005חכמים\u0006 היא \u0005שיסיר אותה\u0006 חבירו \u0005ממנו]\u0006 \u0003ביד\u0004 ולא בכלי, \u0003ותפשוט\u0004 \u0005[ותפתור]\u0006 מכאן את מה שאמר \u0003ר' אלעזר\u0004 בפירושה של משנתנו. ש\u0003אמר ר' אלעזר: מחלוקת ביד, אבל בכלי — דברי הכל חייב!\u0004","ודוחים: \u0003וליטעמיך\u0004 \u0005[לשיטתך]\u0006 לשיטת \u0003ר' אליעזר נמי\u0004 \u0005[גם כן]\u0006 \u0003לישקליה ניהליה\u0004 \u0005[שיסיר אותה ממנו]\u0006 \u0003ביד!\u0004 ותוהים: \u0003האי מאי\u0004 \u0005[זה מהו]\u0006 מה טיבה של קושיה זו? \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שהוא כשיטת \u0003ר' אליעזר היינו דגזר יד אטו\u0004 \u0005[זהו שגזר ביד מפני]\u0006 ה\u0003כלי\u0004 שהרי לשיטתו הנוטל בכלי חייב מן התורה. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003רבנן\u0004 \u0005[\u0006ששיטת \u0005חכמים]\u0006 \u0003היא — נשקליה ניהליה ביד ותו לא מידי\u0004 \u0005[שיסיר אותה ממנו ביד ושוב אינו\u0006 צריך \u0005דבר].\u0006","\u0003כהן שלקה באצבעו\u0004 בשבת — \u0003כורך עליה\u0004 לפי שעה \u0003גמי\u0004 שלא יראה פצוע בשעת עבודת הקודש. והיתר זה — \u0003במקדש אבל לא במדינה\u0004 כיון שהוא גם מרפא, ורפואה שבות הוא. ו\u0003אם\u0004 כוונתו \u0003להוציא דם\u0004 או שיספג הדם — \u0003כאן וכאן אסור.\u0004","\u0003אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: לא שנו\u0004 שמותר \u0003אלא\u0004 כשהניח גמי, \u0003אבל צלצול\u0004 (סרט) \u0003קטן הוי\u0004 \u0005[הוי הוא]\u0006 \u0003יתור בגדים,\u0004 ואסור לכהן להוסיף בגד יתר על בגדי הכהונה האמורים בתורה.","\u0003ור' יוחנן אמר: לא אמרו יתור בגדים\u0004 שיש בו משום עבירה \u0003אלא במקום\u0004 שלובשים בו שאר \u0003בגדים, אבל שלא במקום בגדים\u0004 כגון בידו שאינו מקום לבישת בגד — \u0003לא הוי\u0004 \u0005[אינו]\u0006 \u0003יתור בגדים\u0004 אם קושר שם בגד כלשהו.","ומקשים: \u0003תיפוק ליה\u0004 \u0005[יצא לו]\u0006 שאסור הדבר \u0003משום חציצה,\u0004 שאם היה בגד על ידו נמצא שיש חציצה בינו ובין כלי הקודש ופוסל את העבודה! ודוחים: אפשר לומר \u0003בשמאל,\u0004 שהיה הפצע ביד שמאל, ועבודת המקדש כולה נעשית רק בימין, ולכן החבישה בשמאל אינה חוצצת.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר שהיה הפצע ביד \u0003ימין — ושלא במקום עבודה\u0004 שאין התחבושת חוצצת בינו ובין כלי הקודש.","ושיטה זו \u0003פליגא\u0004 \u0005[חלוקה]\u0006 על שיטת \u0003רבא,\u0004 ש\u0003אמר רבא אמר רב חסדא: במקום בגדים אפילו נימא אחת\u0004 יתרה \u0003חוצצת\u0004 ואסורה, \u0003ושלא במקום בגדים,\u0004 אם היה אריג \u0003שלש על שלש\u0004 אצבעות הריהו נחשב כבגד ולכך \u0003חוצצות, פחות משלש על שלש —\u0004 אינן חוצצות.","ומעירים: הלכה זו על דברי \u0003ר' יוחנן ודאי פליגא\u0004 \u0005[חלוקה]\u0006 שהרי הוא אמר שאין יתור בגדים כלל שלא במקום בגדים. אלא על דברי \u0003רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא מי נימא פליגא\u0004 \u0005[האם נאמר שחלוקה היא]\u0006 שהרי ר' יהודה בן ר' חייא אוסר בצלצול אפילו היה קטן משלוש אצבעות.","ודוחים: לא, אין להוכיח מכאן, כי \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003צלצול קטן דחשיב\u0004 \u0005[שהוא חשוב],\u0006 וכיון שכך הוא נחשב כבגד אף שאין בו שיעור שלוש על שלוש אצבעות.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 \u0003אמרי לה\u0004 \u0005[אומרים אותה]\u0006 מחלוקת באופן זה: \u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: לא שנו\u0004 היתר זה \u0003אלא\u0004 ב\u0003גמי, אבל צלצול קטן\u0004 נחשב כבגד ולכך \u0003חוצץ.\u0004","\u0003ור' יוחנן אמר: לא אמרו חציצה בפחות משלש על שלש אלא במקום בגדים, אבל שלא במקום בגדים\u0004"],["\u0003שלש על שלש\u0004 אצבעות — \u0003חוצצות, פחות משלש — אין חוצצות,\u0004 ואם כן \u0003היינו\u0004 הרי זה אותו דבר שאמר \u0003רבא אמר רב חסדא.\u0004","ושואלים: \u0003לימא פליגא\u0004 \u0005[האם נאמר שחלוקה זו]\u0006 על דברי \u0003רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא?\u0004 ודוחים: אין להוכיח כי \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003צלצול קטן דחשיב\u0004 \u0005[שהוא חשוב]\u0006 והריהו כבגד, ואף רבא מודה שהוא חוצץ.","ולשיטת \u0003ר' יוחנן: אדאשמעינן\u0004 \u0005[עד שהוא משמיע לנו]\u0006 \u0003גמי\u0004 שאפשר להקל בו מטעמים אחרים \u0003לישמעינן\u0004 \u0005[שישמיענו]\u0006 ב\u0003צלצול קטן\u0004 שאפשר לכהן לקושרו ואינו חוצץ!","מסבירים: כי \u0003מילתא אגב אורחיה קא משמע לן, דגמי מסי\u0004 \u0005[דבר בדרך אגב השמיע לנו שהגמי\u0006 מרפא\u0005]\u0006 אלא שאצל כהן עובד לא חששו גם לאיסור ריפוי בשבת שאינו אלא משום שבות ולא נאסרה במקדש.","\u0003בוזקין\u0004 (מפזרים) \u0003מלח על גבי כבש\u0004 שעולים עליו למזבח \u0003בשביל שלא יחליקו\u0004 הכהנים בעלייתם למזבח, \u0003וממלאין\u0004 מים \u0003מבור הגולה ומבור הגדול\u0004 שהיו במקדש על ידי \u0003גלגל\u0004 העשוי לשאוב בו מים אף \u0003בשבת, ומבאר הקר\u0004 רק \u0003ביום טוב.\u0004","\u0003רמי ליה\u0004 \u0005[הראה לו סתירה]\u0006 \u0003רב איקא מפשרוניא לרבא, תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003בוזקין מלח\u0004 בשבת \u0003על גבי הכבש בשביל שלא יחליקו.\u0004 ונדייק מכאן: \u0003במקדש — אין\u0004 \u0005[כן]\u0006 מותר לעשות זאת, \u0003במדינה — לא. ורמינהי\u0004 \u0005[ומקשים על כך]\u0006 שבמקום אחר שנינו: \u0003חצר שנתקלקלה במימי גשמים\u0004 וקשה להלך בה — \u0003מביא תבן ומרדה\u0004 (שוטח, מפזר) \u0003בה\u0004 כדי שיספוג את המים, הרי שמלאכה מעין זו מותרת אפילו במדינה!","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003תבן\u0004 ש\u0003לא מבטיל ליה\u0004 \u0005[מבטל אותו]\u0006 ומתכוון ליטלו משם לאחר שיתייבשו המים, ולכן מותר לשטוח את התבן בחצר כמו שמותר להניחו בכל מקום. אבל דבר ששוטחים אותו במקום ומבטלים אותו שם כמו מלח שלאחר שהלכו עליו ואינו ראוי לשימוש — אסור, מפני שנראה כבונה ומוסיף על הקרקע.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: האי מלח היכי דמי\u0004 \u0005[מלח זה איך הוא בדיוק]\u0006 \u0003אי דמבטליה\u0004 \u0005[אם שמבטל אותו]\u0006 לגבי הכבש \u0003קא\u0004 \u0005[הריהו]\u0006 כ\u0003מוסיף\u0004 על \u0003בנין\u0004 המקדש פרט כלשהו, ועל המקדש \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"הכל בכתב מיד ה' עלי השכיל\u0004 כל מלאכות התבנית\u0003\"\u0004 (דבה\"י א כח, יט) משמע שכל פרט בבנין המקדש נקבע בנבואה ואין לשנותו כלל אפילו ביום חול.","\u0003אי דלא קא מבטליה\u0004 \u0005[אם שלא מבטל אותו]\u0006 את המלח לגבי הכבש, אם כן \u0003קא הויא\u0004 \u0005[הרי זו]\u0006 \u0003חציצה\u0004 בין רגלי הכהנים לכבש, ונמצא שבעת עבודתם אינם דורכים על הכבש ואין עבודתם נעשית כאמור בתורה.","ומשיבים שאין מבטלין את המלח אלא בוזקים אותו רק לצורך \u0003הולכת אברים לכבש, דלאו עבודה היא\u0004 אלא רק הכנה היא לשריפת האיברים.","ושואלים: \u0003ולא\u0004 \u0005[וכי אין\u0006 זו עבודה\u0005]?\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"והקריב הכהן את הכל והקטיר המזבחה\"\u0004 (ויקרא א, יג) \u0003ואמר מר\u0004 \u0005[החכם]\u0006 בפירוש הדבר כי \u0003זו הולכת אברים לכבש,\u0004 הרי שאף זו עבודה הכתובה בתורה! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 שעושים זאת \u0003בהולכת עצים למערכה\u0004 שהולכה זו \u0003לאו\u0004 \u0005[אינה]\u0006 \u0003עבודה היא.\u0004","\u0003דרש רבא: חצר שנתקלקלה במימי גשמים\u0004 בשבת ומלאה בוץ \u0003מביא תבן ומרדה\u0004 (שוטח, מפזר) \u0003בה\u0004 להקל את ההליכה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשהוא מרדה — אינו מרדה לא בסל ולא בקופה\u0004 (סל גדול) \u0003אלא בשולי קופה!\u0004 כלומר שופך את התבן רק בצידיה של הקופה, שלא יעשה כמעשהו בחול, ואילו מדברי רבא נראה שהתיר בכל אופן.","\u0003הדר אוקים\u0004 \u0005[חזר והעמיד]\u0006 \u0003רבא אמורא עליה\u0004 \u0005[מתורגמן לפניו]\u0006 שישמיע דבריו ברבים \u0003ודרש: דברים שאמרתי לפניכם טעות הן בידי, ברם כך אמרו משום\u0004 (בשם) \u0003ר' אליעזר: וכשהוא מרדה אינו מרדה לא בסל ולא בקופה אלא בשולי קופה.\u0004","נאמר במשנה כי \u0003\"ממלאין מבור הגולה\"\u0004 על ידי גלגל. בקשר לנושא זה ולביאורו מסופר: \u0003עולא איקלע לבי\u0004 \u0005[הזדמן לביתו]\u0006 של \u0003רב מנשה, אתא ההוא גברא טרף אבבא\u0004 \u0005[בא אדם אחד והקיש על הדלת]\u0006 \u0003אמר\u0004 עולא: \u0003מאן האי\u0004 \u0005[מי הוא זה]?\u0006 \u0003ליתחל גופיה דקא מחיל ליה לשבתא\u0004 \u0005[יחולל גופו שהוא מחלל את השבת]\u0006 שעובר ומשמיע קול בשבת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: לא אסרו\u0004 בשבת \u0003אלא קול של שיר\u0004 והקשה בדלת אינה קול נעימה. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי לרבה,\u0004 שנינו: \u0003מעלין בדיופי\u0004 (בגישתא, סיפון) לשאוב ממנו מן החבית \u0003ומטיפין מיארק\u0004 (כלי הנוטף טיפות טיפות) \u0003לחולה בשבת.\u0004","ונדייק: \u0003לחולה — אין\u0004 \u0005[כן],\u0006 אבל \u0003לבריא — לא,\u0004 ו\u0003היכי דמי\u0004 \u0005[כיצד היה\u0006 הדבר בדיוק\u0005]\u0006 \u0003לאו דנים וקא בעי דליתער\u0004 \u0005[האם לא שהיה מנמנם ורצו להעירו]\u0006 וכיון שחולה הוא וחוששים להבהילו עושים זאת על ידי קול שפיכת המים מן הכלי. \u0003ושמע מינה: אולודי קלא אסיר\u0004 \u0005[נלמד מכאן שלהוליד קול\u0006 בשבת \u0005אסור]\u0006 ואפילו אינו קול נעימה, שהרי לא התירו אלא לחולה!","ודוחים: \u0003לא,\u0004 מדובר בחולה \u0003דתיר וקא בעי דלינים\u0004 \u0005[ער שרוצים שינמנם]\u0006 לשם כך מטפטפים טיפות דקות \u0003דמשתמע כי קלא דזמזומי\u0004 \u0005[שנשמע כמו קול נגינה].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]:\u0006 \u0003המשמר פירותיו מפני העופות, ודלעיו מפני החיה — משמר כדרכו בשבת\u0004 שאין זו מלאכה אסורה, \u0003ובלבד שלא יספק\u0004 (ימחא כפים) \u0003ולא יטפח\u0004 ידיו על גופו. \u0003ולא ירקד\u0004 וירעיש ברגליו \u0003כדרך שהן עושין בחול\u0004 כדי להבריח את העופות והחיות.","\u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 למה אסור לו\u0005]\u0006 \u0003לאו דקמוליד קלא\u0004 \u0005[האם לא משום שהוא מוליד קול]\u0006 בשבת, \u0003וכל אולודי קלא אסיר\u0004 \u0005[הולדת קול אסורה]?\u0006 \u0003אמר רב אחא בר יעקב:\u0004 לא זה הטעם, אלא משום \u0003גזירה שמא\u0004 אם ינהג כפי שהוא נוהג בחול ישכח ו\u0003יטול צרור\u0004 אבן לזרוק בעופות והריהו מטלטל מוקצה.","ושואלים: \u0003ואלא הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 ש\u0003אמר רב יהודה אמר רב: נשים המשחקות באגוזים\u0004 שמגלגלות אותם על גבי הקרקע עד שיפגעו זה בזה — \u0003אסור. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 \u0003לאו דקא מוליד קלא\u0004 \u0005[האם לא משום שמוליד קול]\u0006 בהקשת האגוזים זה בזה\u0003, וכל אולודי קלא אסיר\u0004 \u0005[וכל הולדת קול אסורה]?\u0006","ודוחים: \u0003לא\u0004 טעם האיסור \u0003דלמא אתי לאשוויי\u0004 \u0005[שמא יבוא להשוות,\u0006 ליישר\u0005]\u0006 ה\u0003גומות,\u0004 שבתוך המשחק יפריעו להן הגומות שבקרקע ויבואו להשוות ולסתום את הגומות בשבת, ויעברו משום בניה.","\u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כן]\u0006 שזהו טעמו של דבר, \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמר רב יהודה: נשים משחקות בתפוחים\u0004 — \u0003אסור, התם מאי אולודי קלא איכא\u0004 \u0005[שם מה הולדת קול יש]\u0006 שהרי אין התפוחים משמיעים קול כשפוגעים זה בזה?! \u0003אלא\u0004 הטעם: \u0003דילמא אתי לאשוויי\u0004 \u0005[שמא יבוא להשוות]\u0006 \u0003גומות\u0004 ואף באגוזים כן.","\u0003תנן\u0004 \u0005[\u0006במשנתנו \u0005שנינו]:\u0006 \u0003ממלאין\u0004 במקדש \u0003מבור הגולה ומבור הגדול בגלגל בשבת,\u0004 ונדייק \u0003במקדש — אין\u0004 \u0005[כן],\u0006 \u0003במדינה — לא. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 \u0003לאו משום דאולודי קלא ואסיר\u0004 \u0005[האם לא משום שהולדת קול הוא ואסור]\u0006 בשבת?","ודוחים: \u0003לא, גזירה שמא ימלא לגינתו ולחורבתו\u0004 כי הגלגל מעלה מים רבים, ואם יתחיל לשאוב מהגלגל שמא יוסיף וישאב מים גם לגינתו, ויעבור משום השקאה בשבת שהיא תולדת מלאכה אסורה.","מסופר כי \u0003אמימר שרא למימלא בגילגלא\u0004 \u0005[התיר למלא\u0006 בשבת \u0005בגלגל]\u0006 \u0003במחוזא,\u0004 ש\u0003אמר: מאי טעמא גזרו רבנן\u0004 \u0005[מה טעם גזרו חכמים]\u0006 \u0003שמא ימלא\u0004 מים \u0003לגינתו ולחורבתו, הכא\u0004 \u0005[כאן]\u0006 במחוזא \u0003לא גינה איכא\u0004 \u0005[יש]\u0006 \u0003ולא חורבה איכא\u0004 \u0005[יש],\u0006 שמחוזא היתה עיר בנויה כולה בלא גינות ושטחים ריקים לזריעה, ולכן אין לחשוש לאיסור.","\u0003כיון דקא חזא\u0004 \u0005[שראה]\u0006 \u0003דקא\u0004"],["\u0003תרו בה כיתנא\u0004 \u0005[ששורין\u0006 במים הללו \u0005פשתן]\u0006 \u0003אסר להו\u0004 \u0005[להם]\u0006 לשאוב מים בגלגל, כדי שלא ימלאו מים לצרכים אסורים.","שנינו במשנה ששואבים \u0003\"מבאר הקר\"\u0004 ושאלו \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003באר הקר? אמר שמואל בור שהקרו\u0004 (שהקריאו) \u0003עליה דברים והתירוה\u0004 שהוכיחו שמן התורה מותר לשאוב ממנה ביום טוב.","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו: \u0003לא כל הבורות הקרות התירו, אלא זו בלבד. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003\"שהקרו דברים עליה\" מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \"בארות הקרות\" בלשון רבים ומה הוא \u0003\"זו בלבד\"\u0004 שהרי אם נגזר שמה ממה שהקריאו עליה, אם כן מה שייכות שם זה לבארות אחרות שלא הקריאו עליהן דבר?","\u0003אלא אמר רב נחמן בר יצחק:\u0004 באר הקר משמע \u0003באר מים חיים, שנאמר \"כהקיר ביר מימיה\u0004 וגו'\u0003\"\u0004 (ירמיה ו, ז) כלומר באר שמימיה נובעים.","\u0003גופא\u0004 \u0005[לגופו\u0006 של דבר\u0005]\u0006 שנינו: \u0003לא כל הבורות הקרות התירו אלא זו בלבד. וכשעלו בני הגולה\u0004 מבבל \u0003חנו עליה, ונביאים שביניהן התירו להן ולא נביאים שביניהן\u0004 (חגי, זכריה ומלאכי) התירו מכוח נבואה \u0003אלא מנהג אבותם בידיהם\u0004 על פי מסורת שמבאר זו היו שואבים אף ביום טוב.","\u0003שרץ\u0004 מת \u0003שנמצא במקדש\u0004 וכאמור בתורה הוא טמא בדרגת אב הטומאה, \u0003כהן מוציאו בשבת בהמיינו\u0004 (באבנטו) ואף שהאבנט, שהוא מבגדי כהונה, נטמא מחמת השרץ מוטב לעשות כן כדי \u0003שלא לשהות את הטומאה\u0004 בבית המקדש, אלו \u0003דברי ר' יוחנן בן ברוקה. ר' יהודה אומר: בצבת של עץ\u0004 מוציאים את השרץ כדי \u0003שלא לרבות את הטומאה\u0004 שצבת כזו אינה מקבלת טומאה.","ברור שביום חול מפנים שרצים מכל מקום שימצאו במקדש, אבל \u0003מהיכן מוציאין אותו\u0004 בשבת — \u0003מן ההיכל, ומן האולם, ומבין האולם למזבח\u0004 שאלה המקומות המקודשים ביותר, ומשאר העזרה אינו צריך, אלו \u0003דברי ר' שמעון בן ננס.\u0004","\u0003ר' עקיבא אומר: כל מקום שחייבין על זדונו כרת ועל שגגתו חטאת\u0004 אם נכנסים שם בטומאה \u0003משם מוציאין אותו\u0004 ובכך נכלל כל שטח העזרה. \u0003ושאר כל המקומות\u0004 שבמקדש \u0003כופין עליו פסכתר\u0004 (גיגית נחושת) ומשאירים אותו כך עד צאת השבת.","\u0003ר' שמעון אומר:\u0004 כלל גדול \u0003מקום שהתירו לך חכמים — משלך נתנו לך שלא התירו לך אלא\u0004 דברים האסורים \u0003משום שבות\u0004 שהיא גזירת חכמים, אבל לא דבר האסור מדין התורה.","\u0003אמר רב טבי בר קיסנא אמר שמואל: המכניס\u0004 דבר שהוא \u0003טמא שרץ למקדש — חייב,\u0004 ואם הכניס \u0003שרץ עצמו — פטור. מאי טעמא\u0004 \u0005[מה טעם\u0006 הבדל זה\u0005]?\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"מזכר ועד נקבה תשלחו\u0004 מחוץ למחנה תשלחום ולא יטמאו את מחניהם אשר אני שוכן בתוכם\u0003\"\u0004 (במדבר ה, ג) כלומר, החובה לשלח מחוץ למחנה חלה רק על \u0003מי שיש לו טהרה במקוה\u0004 כזכר ונקבה האמורים במקרא \u0003יצא שרץ\u0004 עצמו \u0003שאין לו טהרה,\u0004 ולכן המכניס שרץ פטור, שלא עבר על מצות התורה לשלח את הטמאים.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 מברייתא זו ששנינו: \u0003\"מזכר ועד נקבה תשלחו\"\u0004 ונדייק: \u0003פרט לכלי חרש, דברי ר' יוסי הגלילי. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 \u0003לאו משום דלית ליה\u0004 \u0005[האם לא משום שאין לו]\u0006 \u0003טהרה במקוה?\u0004 והוא איפוא כשיטת רב טבי בר קיסנא!","ודוחים: \u0003לא,\u0004 הטעם הוא שמוציאים רק את \u0003מי שנעשה אב הטומאה\u0004 כגון אדם וכלי מתכת. \u0003יצא כלי חרס שאינו נעשה אב הטומאה\u0004 לעולם. וגזרת הכתוב שלכל היותר יהא רק ראשון לטומאה.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם נאמר\u0006 שיש מחלוקת \u0005תנאים]\u0006 בשאלה זו, שהרי במשנתנו נאמר: \u0003שרץ שנמצא במקדש — כהן מוציאו בהמיינו, שלא לשהות את הטומאה,\u0004 אלו \u0003דברי ר' יוחנן בן ברוקה. ר' יהודה אומר: בצבת של עץ מוציאו\u0004 כדי \u0003שלא לרבות את הטומאה.\u0004","\u0003מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא בדבר זה נחלקו]\u0006 \u0003דמאן דאמר\u0004 \u0005[שמי שאמר]\u0006 \u0003שלא לשהות קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003המכניס שרץ למקדש — חייב\u0004 ולכן יש לעשות הכל כדי להוציאו מיד. \u0003ומאן דאמר\u0004 \u0005[ומי שאמר]\u0006 \u0003שלא לרבות\u0004 על ידי טומאת האבנט סבר: \u0003המכניס שרץ למקדש — פטור\u0004 וכיון שאין ציווי מיוחד בדבר ראוי לדאוג שלא להוסיף טומאה יתירה.","את ההסבר הזה דוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 יש לומר שהמכניס שרץ עצמו \u0003חייב. והכא בהא קא מיפלגי\u0004 \u0005[וכאן בזה נחלקו]\u0006 בעצם הטעם שפירשו בדבריהם \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן בן ברוקה\u0005]\u0006 \u0003סבר: שהויי טומאה עדיף\u0004 \u0005[השהיית טומאה עדיפה]\u0006 וחמורה יותר, וכדי שלא תשהה טומאה במקום הקדוש מותר אף לטמא בגדי כהונה. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה\u0005]\u0006 \u0003סבר: אפושי טומאה עדיף\u0004 \u0005[תוספת הטומאה עדיפה]\u0006 וחמורה יותר, ולכן לדעתו אין להוציאו אלא על ידי צבת עץ.","אלא מציעים, אם כן תהא הלכה זו שנויה במחלוקת \u0003כהני תנאי\u0004 \u0005[כתנאים\u0006 אחרים \u0005אלה],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003מהיכן מוציאין אותו\u0004 ונחלקו ר' שמעון בן ננס ור' עקיבא אם מוציאים אותו רק מן ההיכל או אף מן העזרות.","\u0003מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא בדבר זה נחלקו]\u0006 \u0003דמאן דאמר\u0004 \u0005[שמי שאמר]\u0006 ש\u0003מעזרה לא\u0004 מוציאין אותו \u0003קסבר: המכניס שרץ למקדש — פטור,\u0004 ולכן אין חובה להוציאו בשבת מן העזרה, \u0003ומאן דאמר מכולה עזרה\u0004 \u0005[ומי שאמר מכל העזרה\u0006 כולה\u0005]\u0006 חייבים להוציא אותו \u0003סבר\u0004 שהמכניס שרץ למקדש — \u0003חייב.\u0004"],["\u0003אמר ר' יוחנן: ושניהם\u0004 ר' שמעון בן ננס ור' עקיבא שחלקו בכך \u0003מקרא אחד דרשו\u0004 שנאמר \u0003\"ויבאו הכהנים לפנימה בית ה' לטהר ויוציאו את כל הטמאה\u0004 עבודה זרה שטמאה כמת \u0003אשר מצאו בהיכל ה' לחצר בית ה'\u0004 (לעזרה) \u0003ויקבלו הלוים להוציא לנחל קדרון חוצה\"\u0004 (דברי הימים ב כט, טז)","\u0003מר\u0004 \u0005[חכם זה,\u0006 בן ננס\u0005]\u0006 \u0003סבר: מדאשתני\u0004 \u0005[כיון שהשתנו\u0006 הדברים\u0005]\u0006 כי \u0003בעזרה,\u0004 \"חצר בית ה'\", עשו זאת ה\u0003לוים,\u0004 משמע שחובת הוצאת \u0003טומאה בעזרה ליכא\u0004 \u0005[אין כאן]\u0006 ושוב אין הכהנים מצווים על כך.","\u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר: עד היכא דלא אפשר בלוים מפקי\u0004 \u0005[היכן שאי אפשר בלוים מוציאים]\u0006 ה\u0003כהנים,\u0004 שהרי אסור ללוים להיכנס אל ההיכל. \u0003השתא\u0004 \u0005[עכשיו]\u0006 בעזרה ש\u0003אפשר\u0004 להוציא \u0003בלוים תו לא מטמאי\u0004 \u0005[שוב אין מטמאים]\u0006 ה\u0003כהנים\u0004 שאסור להם להיטמא, אלא הלוים מוציאים מאותו מקום שהם יכולים להיכנס בו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הכל נכנסין בהיכל\u0004 אם המטרה היא \u0003לבנות\u0004 אותו \u0003לתקן ולהוציא את הטומאה\u0004 מתוכו, אלא \u0003מצוה בכהנים\u0004 אם אפשר, \u0003אם אין שם כהנים — נכנסין לוים, אין שם לוים — נכנסין ישראלים. ואידי ואידי\u0004 \u0005[וזה וזה]\u0006 \u0003טהורים — אין\u0004 \u0005[כן]\u0006 הם הנכנסים, \u0003טמאים — לא.\u0004","\u0003אמר רב הונא: רב כהנא\u0004 שכהן היה \u0003מסייע כהני\u0004 \u0005[לכהנים]\u0006 ומדגיש את מעלת קדושתם, \u0003דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003רב כהנא: מתוך שנאמר\u0004 על כהן בעל מום \u0003\"אך אל הפרכת לא יבא\u0004 ואל המזבח לא יגש כי מום בו ולא יחלל את מקדשי כי אני ה' מקדשם\u0003\"\u0004 (ויקרא כא, כג) \u0003יכול לא יהו כהנים בעלי מומין נכנסין בין האולם ולמזבח לעשות ריקועי פחים\u0004 של זהב עבור בית קודש הקדשים —","\u0003תלמוד לומר \"אך\"\u0004 שהוא ביטוי של מיעוט, ומשמעו: \u0003חלק,\u0004 שאף כי \u0003מצוה בתמימים\u0004 (שלמים, בלי מומים) לכתחילה, אם \u0003אין שם\u0004 כהנים \u0003תמימים — נכנסין בעלי מומין.\u0004 וכן מלכתחילה \u0003מצוה\u0004 בכהנים \u0003טהורין, אין שם טהורין — נכנסין טמאין. אידי ואידי\u0004 \u0005[אלה ואלה]\u0006 \u0003כהנים — אין\u0004 \u0005[כן],\u0006 \u0003ישראלים — לא.\u0004 הרי שלרב כהנא עדיפים כהנים טמאים על ישראלים טהורים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 שאלה\u0005]\u0006 כהן \u0003טמא\u0004 או כהן \u0003בעל מום, איזו מהן נכנס? רב חייא בר אשי אמר רב: טמא נכנס דהא אישתרי\u0004 \u0005[שהרי הותר]\u0006 \u0003בעבודת ציבור.\u0004 שכן בשעה שכל הציבור כולו נטמא, אף הכהנים הטמאים ראויים לעבודה, מה שאין כן בעלי מומים, שלא הותרו בעבודה כלל. \u0003ר' אלעזר אומר: בעל מום נכנס\u0004 שהרי הוא טהור ויש בו קדושת כהונה אף שפסול לעבודה, \u0003דהא אישתרי\u0004 \u0005[שהרי הוא מותר]\u0006 \u0003באכילת קדשים,\u0004 משמע שאף במומו הוא נשאר בקדושת כהונה. שאלה זו לא נפתרה והושארה בגמרא ללא סיכום.","במשנה שנינו: \u0003ר' שמעון אומר\u0004 מה שהתירו חכמים משלך התירו. ושואלים: \u0003ר' שמעון היכא קאי\u0004 \u0005[לאיזה\u0006 דבר במשנה \u0005הוא מתיחס]?\u0006 ומשיבים: \u0003התם קאי\u0004 \u0005[לשם עומד\u0006 מוסבים דבריו\u0005]\u0006 \u0003דתנן\u0004 \u0005[ששנינו ב\u0006משנה\u0005]:\u0006 \u0003מי שהחשיך חוץ לתחום, אפילו אמה אחת לא יכנס. ר' שמעון אומר: אפילו חמש עשרה אמה יכנס, לפי שאין המשוחות\u0004 (המודדים) \u0003ממצעין\u0004 (מדקדקים) \u0003את המדות מפני הטועים.\u0004","\u0003דקאמר תנא קמא\u0004 \u0005[ממה שאמר התנא הראשון]\u0006 \u0003לא יכנס, ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון: יכנס\u0004 וטעמו כפי המבואר — שבאמת מידת התחום מגיעה עד לאותו מקום, ונמצא שמה שנתנו לאדם הוא שלו על פי הדין.","עוד אמר ר' שמעון: \u0003שלא התירו לך אלא משום שבות,\u0004 ושואלים: \u0003היכא קאי\u0004 \u0005[למה הוא מתייחס]?\u0006 ומשיבים: \u0003התם קאי\u0004 \u0005[לשם\u0006 לדברים אלה \u0005מתיחס]\u0006 \u0003דקאמר תנא קמא\u0004 \u0005[\u0006ממה \u0005שאמר התנא הראשון]\u0006 לגבי נימת כינור שבמקדש שנקרעה בשבת — \u0003קושרה. ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון: עונבה,\u0004 וטעמו של דבר:","\u0003עניבה\u0004 ש\u0003לא אתי\u0004 \u0005[בא]\u0006 בשלה \u0003לידי חיוב חטאת\u0004 בכל מקום שהרי עניבה אין בה איסור מלאכה של קשירה כלל \u0003שרו ליה רבנן\u0004 \u0005[התירו לו חכמים],\u0006 אבל \u0003קשירה דאתי\u0004 \u0005[\u0006שיכול \u0005לבוא]\u0006 בשלה \u0003לידי חיוב חטאת\u0004 אם יעשנה מחוץ למקדש \u0003לא שרו ליה רבנן\u0004 \u0005[התירו לו חכמים],\u0006 שלשיטת ר' שמעון לא התירו חכמים אלא דבר שאיסורו הוא משום שבות בלבד.",""]]};
